/// Account state in the blockchain.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct Account {
    /// Total account balance tracked by the state.
    pub balance: Balance,
    /// Account nonce (transaction count).
    pub nonce: u64,
    /// Account code (for smart contracts).
    pub code: Option<Vec<u8>>,
    /// Account storage (for smart contracts).
    pub storage: BTreeMap<Vec<u8>, Vec<u8>>,
    /// Flag indicating if this is a contract account.
    pub is_contract: bool,
    /// Required stake before rewards become fully spendable.
    pub stake_required: Balance,
    /// Amount currently locked toward required stake.
    pub stake_locked: Balance,
    /// Balance available for transfers/spending.
    pub spendable_balance: Balance,
    /// Total rewards earned over account lifetime.
    pub earned_balance_total: Balance,
}

impl Account {
    /// Create a new account with a fully spendable initial balance.
    pub fn new(balance: Balance) -> Self {
        Self {
            balance,
            nonce: 0,
            code: None,
            storage: BTreeMap::default(),
            is_contract: false,
            stake_required: Balance::new(0),
            stake_locked: Balance::new(0),
            spendable_balance: balance,
            earned_balance_total: Balance::new(0),
        }
    }

    /// Create a new contract account.
    pub fn new_contract(balance: Balance, code: Vec<u8>) -> Self {
        Self {
            balance,
            nonce: 0,
            code: Some(code),
            storage: BTreeMap::default(),
            is_contract: true,
            stake_required: Balance::new(0),
            stake_locked: Balance::new(0),
            spendable_balance: balance,
            earned_balance_total: Balance::new(0),
        }
    }
}

/// Durable, canonical outcome of one contribution reward decision (#2460).
///
/// All five fields are required on the serialized wire shape. In particular,
/// `provenance_class` has no serde default here: accepting the legacy
/// `(address, amount, reason)` tuple would recreate the ambiguity this record
/// exists to remove.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct ContributionRewardRecord {
    pub address: Address,
    pub amount: Balance,
    /// Required shape: `contribution:<commit_id>` or `forecast:<commit_id>`.
    pub reason: String,
    pub station_id: String,
    pub provenance_class: ContributionProvenanceClass,
}

impl ContributionRewardRecord {
    pub fn commit_id(&self) -> Option<&str> {
        self.reason
            .strip_prefix("contribution:")
            .or_else(|| self.reason.strip_prefix("forecast:"))
            .filter(|commit_id| !commit_id.is_empty())
    }
}

