#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq)]
pub enum ContributorClass {
    Unverified,
    VerifiedStation,
    TrustedProvider,
}

impl ContributorClass {
    fn as_label(self) -> &'static str {
        match self {
            Self::Unverified => "Unverified",
            Self::VerifiedStation => "Verified Station",
            Self::TrustedProvider => "Trusted Provider",
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct InlinePayloadTierPolicy {
    pub max_inline_payload_bytes: u64,
    pub allowed_format_families: Vec<String>,
}

impl InlinePayloadTierPolicy {
    fn validate(&self, tier_label: &str) -> Result<(), String> {
        if self.max_inline_payload_bytes > 0 && self.allowed_format_families.is_empty() {
            return Err(format!(
                "{tier_label} inline policy requires at least one allowed format family"
            ));
        }
        Ok(())
    }
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct ContributorTierPolicy {
    pub unverified: InlinePayloadTierPolicy,
    pub verified_station: InlinePayloadTierPolicy,
    pub trusted_provider: InlinePayloadTierPolicy,
    #[serde(default)]
    pub trusted_provider_station_ids: FxHashSet<String>,
}

impl ContributorTierPolicy {
    fn validate(&self) -> Result<(), String> {
        if self.unverified.max_inline_payload_bytes != 0 {
            return Err(
                "contributor.unverified.max_inline_payload_bytes must remain 0".to_string(),
            );
        }
        self.unverified.validate("unverified")?;
        self.verified_station.validate("verified_station")?;
        self.trusted_provider.validate("trusted_provider")?;
        Ok(())
    }

    fn policy_for_class(&self, class: ContributorClass) -> &InlinePayloadTierPolicy {
        match class {
            ContributorClass::Unverified => &self.unverified,
            ContributorClass::VerifiedStation => &self.verified_station,
            ContributorClass::TrustedProvider => &self.trusted_provider,
        }
    }
}

impl Default for ContributorTierPolicy {
    fn default() -> Self {
        Self {
            unverified: InlinePayloadTierPolicy {
                max_inline_payload_bytes: 0,
                allowed_format_families: Vec::new(),
            },
            verified_station: InlinePayloadTierPolicy {
                max_inline_payload_bytes: VERIFIED_STATION_INLINE_MAX_BYTES_DEFAULT,
                allowed_format_families: vec![
                    FORMAT_FAMILY_METAR.to_string(),
                    FORMAT_FAMILY_EXTENDED_SENSOR.to_string(),
                ],
            },
            trusted_provider: InlinePayloadTierPolicy {
                max_inline_payload_bytes: TRUSTED_PROVIDER_INLINE_MAX_BYTES_DEFAULT,
                allowed_format_families: vec![
                    FORMAT_FAMILY_METAR.to_string(),
                    FORMAT_FAMILY_SYNOP.to_string(),
                    FORMAT_FAMILY_BUFR_METADATA.to_string(),
                    FORMAT_FAMILY_STRUCTURED.to_string(),
                ],
            },
            trusted_provider_station_ids: FxHashSet::default(),
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct TrustWeightingPolicy {
    pub unverified_weight: f64,
    pub verified_station_weight: f64,
    pub trusted_provider_weight: f64,
}

impl Default for TrustWeightingPolicy {
    fn default() -> Self {
        Self {
            unverified_weight: 1.0,
            verified_station_weight: 1.0,
            trusted_provider_weight: 1.0,
        }
    }
}

impl TrustWeightingPolicy {
    fn validate(&self) -> Result<(), String> {
        fn validate_weight(name: &str, value: f64) -> Result<(), String> {
            if !value.is_finite() || !(0.0..=1.0).contains(&value) {
                return Err(format!("{name} must be a finite value in [0, 1]"));
            }
            Ok(())
        }

        validate_weight("trust.unverified_weight", self.unverified_weight)?;
        validate_weight(
            "trust.verified_station_weight",
            self.verified_station_weight,
        )?;
        validate_weight(
            "trust.trusted_provider_weight",
            self.trusted_provider_weight,
        )?;

        if self.verified_station_weight < self.unverified_weight {
            return Err(
                "trust.verified_station_weight must be >= trust.unverified_weight".to_string(),
            );
        }
        if self.trusted_provider_weight < self.verified_station_weight {
            return Err(
                "trust.trusted_provider_weight must be >= trust.verified_station_weight"
                    .to_string(),
            );
        }
        Ok(())
    }

    fn weight_for_class(&self, class: ContributorClass) -> f64 {
        match class {
            ContributorClass::Unverified => self.unverified_weight,
            ContributorClass::VerifiedStation => self.verified_station_weight,
            ContributorClass::TrustedProvider => self.trusted_provider_weight,
        }
    }
}

