#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct TaskAssignerPolicy {
    pub enabled: bool,
    pub underserved_bonus_multiplier: f64,
    pub redundancy_penalty_multiplier: f64,
}

impl TaskAssignerPolicy {
    /// Maximum allowed value for the underserved bonus multiplier.
    pub const MAX_UNDERSERVED_BONUS: f64 = 3.0;

    pub fn validate(&self) -> Result<(), String> {
        if !self.underserved_bonus_multiplier.is_finite() || self.underserved_bonus_multiplier < 1.0
        {
            return Err(
                "task_assigner.underserved_bonus_multiplier must be finite and >= 1.0".to_string(),
            );
        }
        if self.underserved_bonus_multiplier > Self::MAX_UNDERSERVED_BONUS {
            return Err(format!(
                "task_assigner.underserved_bonus_multiplier must be <= {}",
                Self::MAX_UNDERSERVED_BONUS
            ));
        }
        if !self.redundancy_penalty_multiplier.is_finite()
            || !(0.0..=1.0).contains(&self.redundancy_penalty_multiplier)
        {
            return Err(
                "task_assigner.redundancy_penalty_multiplier must be finite and in [0, 1]"
                    .to_string(),
            );
        }
        Ok(())
    }
}

impl Default for TaskAssignerPolicy {
    fn default() -> Self {
        Self {
            enabled: true,
            underserved_bonus_multiplier: 1.25,
            redundancy_penalty_multiplier: 0.25,
        }
    }
}

