#[derive(Debug, Clone, Default, Serialize, Deserialize, PartialEq, Eq)]
pub struct QualityPolicyEventBandCounters {
    pub high: u64,
    pub borderline: u64,
    pub warning_only: u64,
    pub low: u64,
}

impl QualityPolicyEventBandCounters {
    fn increment(&mut self, band: DataQualityBand) {
        match band {
            DataQualityBand::High => self.high = self.high.saturating_add(1),
            DataQualityBand::Borderline => self.borderline = self.borderline.saturating_add(1),
            DataQualityBand::WarningOnly => self.warning_only = self.warning_only.saturating_add(1),
            DataQualityBand::Low => self.low = self.low.saturating_add(1),
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct QualityPolicyEventArchiveBucket {
    pub block_height: u64,
    pub first_event_id: u64,
    pub last_event_id: u64,
    pub total_events: u64,
    pub challenge_events: u64,
    pub slashing_events: u64,
    pub band_counters: QualityPolicyEventBandCounters,
    pub challenge_band_counters: QualityPolicyEventBandCounters,
    pub slashing_band_counters: QualityPolicyEventBandCounters,
}

impl QualityPolicyEventArchiveBucket {
    fn new(event: &QualityPolicyEventRecord) -> Self {
        let mut bucket = Self {
            block_height: event.block_height,
            first_event_id: event.event_id,
            last_event_id: event.event_id,
            total_events: 0,
            challenge_events: 0,
            slashing_events: 0,
            band_counters: QualityPolicyEventBandCounters::default(),
            challenge_band_counters: QualityPolicyEventBandCounters::default(),
            slashing_band_counters: QualityPolicyEventBandCounters::default(),
        };
        bucket.record(event);
        bucket
    }

    fn record(&mut self, event: &QualityPolicyEventRecord) {
        self.first_event_id = self.first_event_id.min(event.event_id);
        self.last_event_id = self.last_event_id.max(event.event_id);
        self.total_events = self.total_events.saturating_add(1);
        self.band_counters.increment(event.quality_band);
        match event.event_type {
            QualityPolicyEventType::ChallengeTriggered => {
                self.challenge_events = self.challenge_events.saturating_add(1);
                self.challenge_band_counters.increment(event.quality_band);
            },
            QualityPolicyEventType::SlashingApplied => {
                self.slashing_events = self.slashing_events.saturating_add(1);
                self.slashing_band_counters.increment(event.quality_band);
            },
        }
    }
}

