    /// The effective feature schedule WITHOUT applied extensions — genesis
    /// (∪ the per-chain bootstrap, S5) — as `(name, activation)` pairs. Empty
    /// when no schedule is installed (lib tests, uncut chains).
    pub fn base_feature_schedule() -> Vec<(String, u64)> {
        crate::crypto::chain_binding::try_feature_schedule()
            .map(|schedule| schedule.entries().to_vec())
            .unwrap_or_default()
    }

    /// The `(feature, activation)` pairs this state's applied extensions add
    /// to the schedule, in application order.
    pub fn feature_schedule_extension_entries(&self) -> Vec<(String, u64)> {
        self.feature_schedule_extensions
            .iter()
            .flat_map(|applied| {
                applied
                    .entries
                    .iter()
                    .map(|e| (e.feature.clone(), e.activation_height))
            })
            .collect()
    }

    /// Make the process-wide effective schedule (what `feature_active`
    /// answers) reflect THIS state's applied extensions (#3277 S3). Call it
    /// only with the CANONICAL state, at every point where the canonical state
    /// changes: block apply (producer and P2P), reorg, boot load, WAL replay
    /// and snapshot import. A scratch or orphaned state must never be used.
    pub fn refresh_effective_feature_schedule(&self) {
        crate::crypto::chain_binding::refresh_feature_schedule_extensions(
            self.feature_schedule_extension_entries(),
        );
    }

    /// Apply a feature-schedule extension carried at `block_height` (#3277
    /// S2): V1 against the base schedule, then V2–V9 via
    /// [`crate::governance::schedule_extension::validate_extension_against_state`]
    /// with the boot-installed authority. Fails closed — gate inactive,
    /// authority not installed, or any rule broken — and leaves `self`
    /// untouched on failure.
    pub fn apply_feature_schedule_extension(
        &mut self,
        extension: &crate::governance::schedule_extension::SignedFeatureScheduleExtension,
        block_height: u64,
    ) -> Result<(), StateError> {
        let base = Self::base_feature_schedule();
        let authority = crate::governance::schedule_extension::schedule_extension_authority()
            .ok_or_else(|| {
                StateError::Governance(
                    "feature schedule extension rejected (#3277): no schedule-extension \
                     authority installed"
                        .into(),
                )
            })?;
        self.apply_feature_schedule_extension_with(
            extension,
            block_height,
            &authority.context(),
            &base,
        )
    }

    /// [`State::apply_feature_schedule_extension`] with explicit inputs, so
    /// every rule is testable without process-wide installs.
    pub fn apply_feature_schedule_extension_with(
        &mut self,
        extension: &crate::governance::schedule_extension::SignedFeatureScheduleExtension,
        block_height: u64,
        context: &crate::governance::schedule_extension::ScheduleExtensionContext<'_>,
        base_schedule: &[(String, u64)],
    ) -> Result<(), StateError> {
        use crate::governance::schedule_extension as ext;
        // V1: the transaction type itself is gated.
        if !ext::extension_gate_active(base_schedule, block_height) {
            return Err(StateError::InvalidTransition);
        }
        let applied = ext::validate_extension_against_state(
            extension,
            block_height,
            context,
            base_schedule,
            &self.feature_schedule_extensions,
        )
        .map_err(|e| {
            StateError::Governance(format!("feature schedule extension rejected (#3277): {e}"))
        })?;
        self.feature_schedule_extensions.push(applied);
        Ok(())
    }

    pub fn node_share_activation_height(&self) -> Option<u64> {
        Self::base_feature_schedule().into_iter()
            .chain(self.feature_schedule_extension_entries())
            .find(|(name, _)| name == "node_share_settlement").map(|(_, height)| height)
    }

    pub fn begin_node_service_block(&mut self, height: u64, parent_hash: [u8; 32]) -> Result<(), StateError> {
        let Some(activation) = self.node_share_activation_height().filter(|a| height >= *a) else {
            if self.node_bond_registry.is_some() { return Err(StateError::InvalidTransition); }
            return Ok(());
        };
        let authority = crate::governance::schedule_extension::schedule_extension_authority().ok_or(StateError::InvalidTransition)?;
        let context = authority.context();
        if context.network_id != "testnet" || (context.chain_id != "777" && self.genesis_emission_chain_id() != Some(context.chain_id)) {
            return Err(StateError::InvalidTransition);
        }
        let genesis: [u8; 32] = hex::decode(context.genesis_hash).map_err(|_| StateError::InvalidTransition)?
            .try_into().map_err(|_| StateError::InvalidTransition)?;
        if height != activation && (self.node_receipt_registry.is_none() || self.node_settlement.is_none() || self.node_fraud.is_none()) {
            return Err(StateError::InvalidTransition);
        }
        let challenge = crate::consensus::node_share_contracts::node_challenge_blocks(self.genesis_emission_chain_id());
        if let Some(registry) = &mut self.node_bond_registry {
            if registry.activation_height != activation || registry.genesis_hash != genesis { return Err(StateError::InvalidTransition); }
            registry.advance_with_challenge(height, parent_hash, challenge)?;
        } else {
            self.node_bond_registry = Some(crate::consensus::node_bond_registry::NodeBondRegistry::begin(activation, genesis, height, parent_hash)?);
        }
        if self.node_receipt_registry.is_none() {
            if height != activation { return Err(StateError::InvalidTransition); }
            self.node_receipt_registry = Some(Default::default());
        }
        self.node_receipt_registry.as_mut().expect("marker set").advance(self.node_bond_registry.as_ref().expect("registry set"));
        if self.node_settlement.is_none() {
            if height != activation { return Err(StateError::InvalidTransition); }
            self.node_settlement = Some(Default::default());
        }
        if self.node_fraud.is_none() {
            if height != activation { return Err(StateError::InvalidTransition); }
            let adopted = if let Some(sink) = self.accounts.get_mut(&crate::consensus::node_fraud::forfeiture_address()) {
                // Adopt existing OFF-path funds without changing balance or supply.
                sink.stake_locked = sink.balance;
                sink.stake_required = sink.balance;
                sink.spendable_balance = Balance::new(0);
                sink.balance.0
            } else { 0 };
            self.node_fraud = Some(crate::consensus::node_fraud::NodeFraudState { adopted, ..Default::default() });
        }
        self.node_fraud.as_mut().expect("fraud marker set").advance(self.node_bond_registry.as_ref().expect("registry set"));
        self.open_emission_block(height);
        let supply = self.checked_total_minted_supply()?;
        self.emission_ledger.set_cached_supply(supply);
        Ok(())
    }

    pub fn validate_node_bond_anchor(&self, height: u64) -> Result<(), StateError> {
        let active = self.node_share_activation_height().filter(|activation| height >= *activation);
        match (&self.node_bond_registry, active) {
            (None, None) if self.node_receipt_registry.is_none() && self.node_settlement.is_none() && self.node_fraud.is_none() => Ok(()),
            (Some(registry), Some(activation)) if registry.activation_height == activation && registry.block_height == height => {
                if registry.registrations.len() > crate::consensus::node_share_contracts::MAX_NODE_REGISTRATIONS
                    || registry.lifecycle_tx_count > crate::consensus::node_bond_registry::MAX_NODE_BOND_LIFECYCLE_TXS_PER_BLOCK as u64
                    || registry.frozen_epochs.len() > crate::consensus::node_bond_registry::max_retained_node_epochs(self.genesis_emission_chain_id()) {
                    return Err(StateError::InvalidTransition);
                }
                let epoch = crate::consensus::node_bond_registry::epoch_at(activation, height).ok_or(StateError::InvalidTransition)?;
                if !registry.frozen_epochs.contains_key(&epoch) { return Err(StateError::InvalidTransition); }
                for (frozen_epoch, frozen) in &registry.frozen_epochs {
                    if *frozen_epoch > epoch || frozen.bindings.len() > crate::consensus::node_share_contracts::MAX_NODE_REGISTRATIONS
                        || frozen.roster_sequence > registry.sequence {
                        return Err(StateError::InvalidTransition);
                    }
                }
                for r in registry.registrations.values() {
                    if !self.accounts.contains_key(&r.binding.owner_account) { return Err(StateError::InvalidTransition); }
                    let escrow = self.accounts.get(&r.binding.escrow_account).ok_or(StateError::AccountNotFound)?;
                    let amount = Balance::new(u128::from(r.principal_units));
                    if r.principal_units > crate::consensus::node_bond_registry::NODE_BOND_UNITS
                        || escrow.balance != amount || escrow.stake_locked != amount || escrow.spendable_balance != Balance::new(0) {
                        return Err(StateError::InvalidTransition);
                    }
                }
                crate::consensus::node_receipt_registry::validate_receipt_anchor(self, height)?;
                self.node_settlement.as_ref().ok_or(StateError::InvalidTransition)?.validate(self, height)?;
                self.node_fraud.as_ref().ok_or(StateError::InvalidTransition)?.validate(self, height)?;
                Ok(())
            },
            _ => Err(StateError::InvalidTransition),
        }
    }

    fn apply_node_bond_lifecycle(&mut self, payload: &crate::consensus::node_bond_registry::NodeBondLifecycle, height: u64) -> Result<(), StateError> {
        if !self.node_share_activation_height().is_some_and(|activation| height >= activation) { return Err(StateError::InvalidTransition); }
        let authority = crate::governance::schedule_extension::schedule_extension_authority().ok_or(StateError::InvalidTransition)?;
        let context = authority.context();
        let genesis: [u8; 32] = hex::decode(context.genesis_hash).map_err(|_| StateError::InvalidTransition)?
            .try_into().map_err(|_| StateError::InvalidTransition)?;
        crate::consensus::node_bond_registry::apply_lifecycle(self, payload, height,
            &crate::crypto::chain_binding::ChainIdentity::new(context.chain_id, context.network_id), &genesis, context.allowlist)
    }

    pub fn get_account(&self, address: &Address) -> Option<&Account> {
        self.accounts.get(address)
    }

    pub fn validate_node_finalized(&self, height: u64) -> Result<(), StateError> {
        if let Some(store) = &self.node_settlement {
            if store.last_finalized_height != Some(height) { return Err(StateError::InvalidTransition); }
            store.validate(self,height)?;
        }
        Ok(())
    }

    pub fn get_account_mut(&mut self, address: &Address) -> Option<&mut Account> {
        self.accounts.get_mut(address)
    }

    /// Access the oracle registry (read-only).
    pub fn oracle_registry(&self) -> &OracleRegistry {
        &self.oracle_registry
    }

    /// Access the oracle registry (mutable) — use for seeding reputation scores in tests.
    pub fn oracle_registry_mut(&mut self) -> &mut OracleRegistry {
        &mut self.oracle_registry
    }

    /// Replace the ZK verifier used during state transition validation.
    pub fn set_zk_verifier(
        &mut self,
        verifier: std::sync::Arc<dyn crate::consensus::zk_verification::ZkVerifier>,
    ) {
        self.zk_verifier = verifier;
    }

    /// Returns the total supply currently held across all accounts.
    pub fn checked_total_minted_supply(&self) -> Result<u128, StateError> {
        self.accounts.values().try_fold(0u128, |sum, a| sum.checked_add(a.balance.0))
            .ok_or(StateError::ArithmeticOverflow)
    }
    /// Rebuild nonserialized ledger views after snapshot/checkpoint decoding.
    /// With Node settlement ON, Node spending is exclusively unminted reserve;
    /// redemption uses prior authorization and never charges this slice.
    pub fn restore_node_emission_runtime(&mut self) -> Result<(), StateError> {
        if self.node_settlement.is_some() {
            let supply = self.checked_total_minted_supply()?;
            self.emission_ledger.set_cached_supply(supply);
            self.emission_ledger.restore_node_reservation();
        }
        Ok(())
    }

    pub fn outstanding_node_reserves(&self) -> u128 {
        self.node_settlement.as_ref().map_or(0, |s| s.outstanding)
    }
    pub fn issuance_committed_supply(&self) -> u128 {
        self.emission_ledger.cached_supply().unwrap_or_else(|| self.checked_total_minted_supply().unwrap_or(u128::MAX))
            .saturating_add(self.outstanding_node_reserves())
    }
    pub fn mint_headroom(&self) -> u128 {
        crate::consensus::proof_of_publishing::MAX_SUPPLY.saturating_sub(self.issuance_committed_supply())
    }

    pub fn total_minted_supply(&self) -> u128 {
        self.accounts.values().map(|a| a.balance.0).sum()
    }

    pub fn create_account(&mut self, address: Address, initial_balance: Balance) -> &mut Account {
        self.accounts
            .entry(address)
            .or_insert_with(|| Account::new(initial_balance))
    }

    /// Provenance-separated contribution reward totals for one address.
    ///
    /// Iteration is canonical because the underlying record collection is a
    /// BTreeMap. Only finalized records contribute to paid totals; a positive
    /// real plan awaiting quorum is reported separately.
    pub fn contribution_reward_aggregate(
        &self,
        address: &Address,
    ) -> ContributionRewardAggregate {
        let mut aggregate = ContributionRewardAggregate::default();
        for (commit_id, record) in &self.contribution_reward_records {
            if &record.address != address {
                continue;
            }
            let finalized = self.finalized_contribution_rewards.contains(commit_id);
            match record.provenance_class {
                ContributionProvenanceClass::Real => {
                    aggregate.real_decision_count =
                        aggregate.real_decision_count.saturating_add(1);
                    if finalized {
                        aggregate.real_paid += record.amount;
                    } else {
                        aggregate.real_pending += record.amount;
                    }
                },
                ContributionProvenanceClass::Synthetic => {
                    aggregate.synthetic_decision_count =
                        aggregate.synthetic_decision_count.saturating_add(1);
                    if finalized {
                        aggregate.synthetic_paid += record.amount;
                    }
                },
                ContributionProvenanceClass::Unclassified => {
                    aggregate.unclassified_decision_count =
                        aggregate.unclassified_decision_count.saturating_add(1);
                    if finalized {
                        aggregate.unclassified_paid += record.amount;
                    }
                },
            }
        }
        aggregate
    }

    fn active_station_cell(&self, station_id: &str) -> Option<GeoCell> {
        let station = self.station_registry.get(station_id)?;
        if !station.is_active {
            return None;
        }

        Some(crate::consensus::data_desert::cell_for_station(
            station.location.latitude,
            station.location.longitude,
        ))
    }

    /// Register a weather station and update geographic density counters.
    pub fn register_weather_station(&mut self, station: WeatherStation) -> Result<(), StateError> {
        let is_active = station.is_active;
        let cell = crate::consensus::data_desert::cell_for_station(
            station.location.latitude,
            station.location.longitude,
        );
        self.station_registry
            .register(station)
            .map_err(|e| StateError::Governance(format!("station registration failed: {e}")))?;

        if is_active {
            let entry = self.station_counts.entry(cell).or_insert(0);
            *entry = entry.saturating_add(1);
        }

        Ok(())
    }

    /// Apply a governance-authorized station registration (#2537).
    ///
    /// The deterministic, replay-safe form of [`Self::register_weather_station`]:
    /// an upsert that keeps `station_counts` — which is folded into
    /// `state_root` — exactly consistent with `station_registry`.
    ///
    /// The counter bookkeeping is the subtle part. A re-registration can change
    /// both the cell (coordinates moved) and the active flag, so the previous
    /// record's contribution must be withdrawn from its OWN cell before the new
    /// one is added. Deriving the old cell from the new coordinates would
    /// decrement the wrong bucket and silently diverge peers that replayed the
    /// two registrations in the same order.
    pub fn apply_station_registration(
        &mut self,
        station: WeatherStation,
    ) -> Result<(), StateError> {
        let is_active = station.is_active;
        let new_cell = crate::consensus::data_desert::cell_for_station(
            station.location.latitude,
            station.location.longitude,
        );

        let previous = self
            .station_registry
            .upsert(station)
            .map_err(|e| StateError::Governance(format!("station registration failed: {e}")))?;

        if let Some(previous) = previous {
            if previous.is_active {
                let old_cell = crate::consensus::data_desert::cell_for_station(
                    previous.location.latitude,
                    previous.location.longitude,
                );
                if let Some(count) = self.station_counts.get_mut(&old_cell) {
                    *count = count.saturating_sub(1);
                    if *count == 0 {
                        self.station_counts.remove(&old_cell);
                    }
                }
            }
        }

        if is_active {
            let entry = self.station_counts.entry(new_cell).or_insert(0);
            *entry = entry.saturating_add(1);
        }

        Ok(())
    }

    /// #3345: would applying `station` change the owner already registered
    /// for its `station_id`?
    ///
    /// `false` for a station that is not registered yet (a first
    /// registration has no owner to protect). Two owner strings name the same
    /// owner when they are byte-identical, or when both parse to the same 20
    /// raw address bytes under the presentations the registry accepts (`0x…`,
    /// `wrf…`, bare hex) — so a metadata re-registration that merely re-spells
    /// the same address is not mistaken for a transfer. Anything else is an
    /// owner change.
    pub fn station_registration_changes_owner(&self, station: &WeatherStation) -> bool {
        let Some(existing) = self.station_registry.get(&station.station_id) else {
            return false;
        };
        !same_station_owner(&existing.owner_address, &station.owner_address)
    }

    /// Deactivate a weather station and decrement the corresponding cell counter.
    pub fn deactivate_weather_station(&mut self, station_id: &str) -> bool {
        let cell = self.active_station_cell(station_id);
        let was_active = self.station_registry.deactivate(station_id);
        if !was_active {
            return false;
        }

        if let Some(cell) = cell {
            if let Some(count) = self.station_counts.get_mut(&cell) {
                *count = count.saturating_sub(1);
                if *count == 0 {
                    self.station_counts.remove(&cell);
                }
            }
        }

        true
    }

    /// Resolve an active station's quantized grid cell.
    pub fn station_cell(&self, station_id: &str) -> Option<GeoCell> {
        self.active_station_cell(station_id)
    }

    /// Resolve an active station's coordinates.
    pub fn station_coordinates(&self, station_id: &str) -> Option<(f64, f64)> {
        let station = self.station_registry.get(station_id)?;
        if !station.is_active {
            return None;
        }

        Some((station.location.latitude, station.location.longitude))
    }

    /// Resolve the on-chain account that is economically accountable for a
    /// station's data-quality violations.
    ///
    /// A station id is an application identifier, not an account address. A
    /// data-quality trigger must therefore bind to the registered owner before
    /// it enters the deferred slashing queue. Requiring the account here keeps
    /// finalization from degrading into the old logged-and-skipped no-op.
    fn station_slash_identity(&self, station_id: &str) -> Result<String, StateError> {
        let station = self.station_registry.get(station_id).ok_or_else(|| {
            StateError::SlashingApplication(format!(
                "cannot resolve slashable owner for unregistered station '{station_id}'"
            ))
        })?;
        // Station registration accepts the canonical `wrf…` wallet form
        // returned by `PublicKey::to_address()` as well as the internal
        // `0x…` representation used by `Address`. Normalize both through the
        // parsed account so the deferred trigger always carries one canonical
        // identity and cannot silently miss the funded account.
        let owner_text = station
            .owner_address
            .strip_prefix("wrf")
            .unwrap_or(&station.owner_address);
        let owner = Address::from_hex(owner_text).map_err(|_| {
            StateError::SlashingApplication(format!(
                "station '{station_id}' owner_address '{}' is not a slashable account address",
                station.owner_address
            ))
        })?;
        if !self.accounts.contains_key(&owner) {
            return Err(StateError::SlashingApplication(format!(
                "station '{station_id}' owner_address '{}' has no on-chain account to slash",
                station.owner_address
            )));
        }
        Ok(owner.to_string())
    }

    /// Build the capability evidence record for a contributor at a given
    /// block height (#735).
    ///
    /// This is the **stub** landing site for the evidence accumulation
    /// path. Today it returns an empty record with `window_blocks` set so
    /// that downstream scoring produces the default `1.0×` multiplier
    /// (consistent with the default-disabled
    /// [`crate::consensus::capability::CapabilityMultiplierPolicy`]).
    ///
    /// Follow-up work populates the aggregate counts from committed
    /// observations inside the sliding window — at that point the method
    /// body grows but the signature and contract remain the same.
    ///
    /// Leaving the stub in place now gives the reward path a stable
    /// integration point and lets tests exercise the plumbing (with
    /// evidence injected via governance proposals or test harnesses)
    /// without waiting for the accumulation PR to land.
    pub fn capability_evidence_for_contributor(
        &self,
        _contributor: &Address,
        window_blocks: u64,
        _current_height: u64,
    ) -> ContributorCapabilityEvidence {
        ContributorCapabilityEvidence::empty(window_blocks)
    }

    /// Record an oracle-local accuracy score for a station's cell.
    pub fn record_oracle_local_accuracy(
        &mut self,
        oracle_id: &str,
        station_id: &str,
        score_bps: u32,
        window: u32,
    ) -> Option<u32> {
        let cell = self.station_cell(station_id)?;
        let key = (oracle_id.to_string(), cell);
        let record = self
            .oracle_local_accuracy
            .entry(key)
            .or_insert_with(|| OracleLocalAccuracy {
                oracle_id: oracle_id.to_string(),
                cell,
                ..OracleLocalAccuracy::default()
            });
        record.push_score(score_bps, window);
        Some(record.mean_accuracy_bps())
    }

    /// Return a clone of oracle-local accuracy for an oracle/station cell pair.
    pub fn oracle_local_accuracy_for_station(
        &self,
        oracle_id: &str,
        station_id: &str,
    ) -> Option<OracleLocalAccuracy> {
        let cell = self.station_cell(station_id)?;
        self.oracle_local_accuracy
            .get(&(oracle_id.to_string(), cell))
            .cloned()
    }

    fn apply_oracle_slashing_trigger(
        &mut self,
        trigger: &SlashingTrigger,
        block_height: u64,
    ) -> Result<(), StateError> {
        let oracle_id = trigger.oracle_id().to_string();

        // Cooldown is deterministic per-oracle — safe to check eagerly.
        if self.oracle_registry.is_in_cooldown(&oracle_id, block_height) {
            warn!(
                "Slashing cooldown: oracle {} was recently slashed, skipping (cooldown {} blocks)",
                oracle_id,
                crate::oracle::attestation::SLASHING_COOLDOWN_BLOCKS
            );
            return Ok(());
        }

        // Defer the trigger — circuit breaker cap is applied in deterministic
        // oracle_id order during flush_deferred_slashing() (issue #873).
        self.deferred_slashing_triggers
            .push((trigger.clone(), block_height));
        Ok(())
    }

    /// Apply a single slashing trigger's reputation, balance, and cooldown effects.
    /// Extracted from the former inline `apply_oracle_slashing_trigger` body.
    fn apply_slashing_trigger_inner(&mut self, trigger: &SlashingTrigger, block_height: u64) {
        let oracle_id = trigger.oracle_id().to_string();

        // Reputation penalty.
        match trigger {
            SlashingTrigger::InvalidSignature { oracle_id, .. } => {
                self.oracle_registry
                    .apply_reputation_event(ReputationEvent {
                        oracle_id: oracle_id.clone(),
                        delta: -10,
                        reason: "invalid_signature".to_string(),
                        timestamp: block_height,
                    });
            },
            SlashingTrigger::DoubleAttestation { oracle_id, .. } => {
                self.oracle_registry
                    .apply_reputation_event(ReputationEvent {
                        oracle_id: oracle_id.clone(),
                        delta: -15,
                        reason: "double_attestation".to_string(),
                        timestamp: block_height,
                    });
            },
            SlashingTrigger::InvalidWeatherProof { oracle_id, .. } => {
                self.oracle_registry
                    .apply_reputation_event(ReputationEvent {
                        oracle_id: oracle_id.clone(),
                        delta: -10,
                        reason: "invalid_zk_proof".to_string(),
                        timestamp: block_height,
                    });
            },
            SlashingTrigger::DataQualityViolation { oracle_id, .. } => {
                self.oracle_registry
                    .apply_reputation_event(ReputationEvent {
                        oracle_id: oracle_id.clone(),
                        delta: -5,
                        reason: "data_quality_violation".to_string(),
                        timestamp: block_height,
                    });
            },
            SlashingTrigger::OracleNotRegistered { .. } => {},
        }

        let oracle_count = self.oracle_registry.oracle_count();
        let Some(event) = self
            .slashing_engine
            .evaluate_oracle_trigger(trigger, oracle_count, block_height)
        else {
            warn!("slashing trigger did not produce an event for {}", oracle_id);
            return;
        };

        // Wire metric increment and per-reason counter for monitoring snapshot (#683).
        CORE_METRICS.inc_slashing_event(&event.reason);
        *self.slashing_reason_counts.entry(event.reason.clone()).or_insert(0) += 1;

        let address = event
            .address_or_oracle_id
            .parse::<Address>()
            .or_else(|_| {
                crate::crypto::signature::PublicKey::from_hex(&event.address_or_oracle_id)
                    .map_err(|_| {
                        StateError::SlashingApplication(format!(
                            "cannot map oracle identifier '{}' to slashable account address",
                            event.address_or_oracle_id
                        ))
                    })
                    .and_then(|public_key| {
                        Address::from_hex(public_key.to_address().trim_start_matches("wrf"))
                            .map_err(|_| {
                                StateError::SlashingApplication(format!(
                                    "cannot derive slashable account address from oracle identifier '{}'",
                                    event.address_or_oracle_id
                                ))
                            })
                    })
            });
        match address {
            Ok(addr) => {
                if let Err(err) = self.apply_transition(StateTransition::Slash {
                    address: addr,
                    amount: Balance::new(event.amount),
                    reason: format!("{:?}", event.reason),
                }) {
                    warn!(
                        "oracle slashing for {:?} is a no-op (account may have zero balance): {err}",
                        trigger
                    );
                }
            }
            Err(e) => {
                warn!("skipping balance slash for {}: {e}", oracle_id);
            }
        }

        // Record cooldown.
        self.oracle_registry.record_slash(&oracle_id, block_height);
    }

    /// Flush all deferred slashing triggers in deterministic `oracle_id` order,
    /// applying the circuit breaker cap. Must be called once at end-of-block.
    pub fn flush_deferred_slashing(&mut self) {
        let mut triggers = std::mem::take(&mut self.deferred_slashing_triggers);
        triggers.sort_by(|(a, _), (b, _)| a.oracle_id().cmp(b.oracle_id()));

        self.slashing_circuit_breaker.reset();
        for (trigger, height) in triggers {
            if self.slashing_circuit_breaker.would_exceed_cap() {
                warn!(
                    "Circuit breaker cap reached, skipping slash for {}",
                    trigger.oracle_id()
                );
                self.slashing_circuit_breaker.record_skipped();
                continue;
            }
            self.apply_slashing_trigger_inner(&trigger, height);
            self.slashing_circuit_breaker.record_slash();
        }

        // Bound the engine's streak counters to the active oracle set so the
        // map cannot grow unbounded across blocks (#1408, #841). Safe to run
        // every block because `low_quality_counters` is `#[serde(skip)]` —
        // it does not contribute to the state root.
        let oracle_set = &self.oracle_set;
        self.slashing_engine
            .prune_counters(|participant| oracle_set.contains(participant));
    }

    pub fn set_stake_required(&mut self, address: Address, stake_required: Balance) {
        let account = self.create_account(address, Balance::new(0));
        account.stake_required = stake_required;
    }

    pub fn reset_low_quality_streak(&mut self, address: &Address) {
        self.low_quality_streaks.remove(address);
    }

    pub fn increment_low_quality_streak(&mut self, address: Address) -> u32 {
        let streak = self.low_quality_streaks.entry(address).or_insert(0);
        *streak = streak.saturating_add(1);
        *streak
    }

    pub fn append_quality_policy_event(&mut self, mut event: QualityPolicyEventRecord) -> u64 {
        let next_id = self
            .quality_policy_events
            .last()
            .map(|last| last.event_id.saturating_add(1))
            .or_else(|| {
                self.archived_quality_policy_event_through_event_id
                    .map(|id| id.saturating_add(1))
            })
            .unwrap_or(1);
        event.event_id = next_id;
        self.quality_policy_events.push(event);
        self.prune_quality_policy_events_to_policy_limit();
        next_id
    }

    pub fn append_audit_event(&mut self, mut event: AuditEventRecord) -> u64 {
        let next_id = self
            .audit_events
            .last()
            .map(|last| last.event_id.saturating_add(1))
            .unwrap_or(1);
        event.event_id = next_id;
        self.audit_events.push(event);
        next_id
    }

    pub fn quality_policy_events(&self) -> &[QualityPolicyEventRecord] {
        &self.quality_policy_events
    }

    /// Returns cumulative slashing event counts keyed by stable string label,
    /// for use in monitoring snapshots (#683).
    pub fn slashing_events_by_reason(&self) -> HashMap<String, u64> {
        self.slashing_reason_counts
            .iter()
            .map(|(reason, &count)| (reason.as_str().to_string(), count))
            .collect()
    }

    pub fn audit_events(&self) -> &[AuditEventRecord] {
        &self.audit_events
    }

    pub fn quality_policy_event_archive(&self) -> &[QualityPolicyEventArchiveBucket] {
        &self.quality_policy_event_archive
    }

    pub fn archived_quality_policy_event_count(&self) -> u64 {
        self.archived_quality_policy_event_count
    }

    pub fn archived_quality_policy_event_through_event_id(&self) -> Option<u64> {
        self.archived_quality_policy_event_through_event_id
    }

    pub fn hot_quality_policy_event_frontier(&self) -> Option<(u64, u64)> {
        self.quality_policy_events
            .first()
            .map(|event| (event.event_id, event.block_height))
    }

    pub fn quality_event_retention_policy(&self) -> &QualityEventRetentionPolicy {
        &self.governance.params.quality_event_retention_policy
    }

    fn prune_quality_policy_events_to_policy_limit(&mut self) {
        let limit = self
            .governance
            .params
            .quality_event_retention_policy
            .hot_event_limit
            .max(1) as usize;
        if self.quality_policy_events.len() <= limit {
            return;
        }

        let evict_count = self.quality_policy_events.len().saturating_sub(limit);
        let evicted = self
            .quality_policy_events
            .drain(0..evict_count)
            .collect::<Vec<_>>();
        for event in evicted {
            self.archive_quality_policy_event(&event);
        }
    }

    fn archive_quality_policy_event(&mut self, event: &QualityPolicyEventRecord) {
        self.archived_quality_policy_event_count =
            self.archived_quality_policy_event_count.saturating_add(1);
        self.archived_quality_policy_event_through_event_id = Some(
            event.event_id.max(
                self.archived_quality_policy_event_through_event_id
                    .unwrap_or_default(),
            ),
        );

        match self
            .quality_policy_event_archive
            .binary_search_by_key(&event.block_height, |bucket| bucket.block_height)
        {
            Ok(index) => {
                self.quality_policy_event_archive[index].record(event);
            },
            Err(index) => {
                self.quality_policy_event_archive
                    .insert(index, QualityPolicyEventArchiveBucket::new(event));
            },
        }
    }

    /// Seed the initial authorized block-producer set at genesis (#2290). The
    /// GENESIS-SEED hook Alice calls: installs one `epoch 0 / effective_height 0`
    /// change, authoritative from height 1 (enforce-at-genesis). Fail-closed —
    /// the members are validated (non-empty, canonical payout addresses, no dup
    /// id/key, well-formed keys) before install. Does NOT recalculate the root;
    /// the caller recomputes once genesis state is fully built.
    pub fn seed_genesis_producer_set(
        &mut self,
        members: Vec<crate::consensus::producer_set::ProducerMember>,
    ) -> Result<(), StateError> {
        let change = crate::consensus::producer_set::ProducerSetChange::new(0, 0, members);
        crate::consensus::producer_set::validate_producer_set_history(std::slice::from_ref(&change))
            .map_err(|e| {
                StateError::Governance(format!("invalid genesis producer set (#2290): {e:?}"))
            })?;
        self.producer_set_history = vec![change];
        Ok(())
    }

    pub fn set_oracle_config(
        &mut self,
        oracle_set: FxHashSet<String>,
        oracle_quorum: usize,
    ) -> Result<(), StateError> {
        Self::validate_oracle_config(&oracle_set, oracle_quorum)?;
        self.oracle_set = oracle_set.clone();
        self.oracle_quorum = oracle_quorum;
        self.oracle_registry = OracleRegistry::with_params(oracle_set, self.oracle_quorum);
        self.ensure_legacy_oracle_keys()?;
        Ok(())
    }

