    fn oracle_identity(seed: u64) -> (PrivateKey, String) {
        let mut rng = StdRng::seed_from_u64(seed);
        let private_key = PrivateKey::generate(&mut rng);
        let oracle_id = PublicKey::from_private_key(&private_key).to_string();
        (private_key, oracle_id)
    }

    /// Deterministic governance voter identity from a seed (#933).
    fn governance_voter(seed: u64) -> (PrivateKey, PublicKey, Address) {
        let mut rng = StdRng::seed_from_u64(seed);
        let private_key = PrivateKey::generate(&mut rng);
        let public_key = PublicKey::from_private_key(&private_key);
        let address = Address::from_public_key(&public_key);
        (private_key, public_key, address)
    }

    /// Create a signed GovernanceVotePayload JSON string (#933).
    fn signed_vote_json(
        proposal_id: &str,
        approve: bool,
        voting_power: Option<u64>,
        private_key: &PrivateKey,
        public_key: &PublicKey,
    ) -> String {
        let mut payload = GovernanceVotePayload {
            proposal_id: proposal_id.to_string(),
            approve,
            voting_power,
            signature: None,
            // #2229: the domain body binds `signer_public_key`, so it must be
            // set before the preimage is computed.
            signer_public_key: Some(public_key.to_hex()),
        };
        // #2229: sign the version-appropriate preimage — legacy string at V1,
        // domain-separated at V2 — matching `verify_vote_signature`. Tests run at
        // the ambient default (V1) unless a V2 identity is installed.
        let signature = match crate::crypto::chain_binding::SigningProtocolVersion::active() {
            crate::crypto::chain_binding::SigningProtocolVersion::V1 => {
                private_key.sign(payload.canonical_signing_message().as_bytes())
            },
            crate::crypto::chain_binding::SigningProtocolVersion::V2 => {
                crate::crypto::domain_signing::sign_domain(private_key, &payload)
            },
        };
        payload.signature = Some(signature.to_hex());
        serde_json::to_string(&payload).unwrap()
    }

    fn signed_attestation(
        private_key: &PrivateKey,
        oracle_id: &str,
        commit_id: &str,
        approved: bool,
        confidence: f64,
        timestamp: i64,
    ) -> OracleAttestationPayload {
        // Generate a deterministic nonce from the inputs so the nonce guard (#1844) is satisfied.
        let nonce = format!("{oracle_id}:{commit_id}:{timestamp}");
        let mut payload = OracleAttestationPayload {
            commit_id: commit_id.to_string(),
            oracle_id: oracle_id.to_string(),
            approved,
            signature: None,
            confidence: Some(confidence),
            timestamp,
            nonce: Some(nonce),
        };
        let message = payload.signing_message();
        payload.signature = Some(private_key.sign(message.as_bytes()).to_string());
        payload
    }

    fn selective_disclosure_proof(
        disclosure_id: &str,
        scope: &[&str],
        expires_at_block: u64,
    ) -> SelectiveDisclosureProofPayload {
        let (private_key, _) = oracle_identity(9_121);
        let disclosed_fields_hash = "cd".repeat(PRIVACY_DISCLOSED_FIELDS_HASH_BYTES);
        let mut disclosure = SelectiveDisclosureProofPayload {
            disclosure_id: disclosure_id.to_string(),
            scope: scope.iter().map(ToString::to_string).collect(),
            expires_at_block,
            disclosed_fields_hash,
            verifier_attestation: String::new(),
        };
        disclosure.verifier_attestation =
            private_key.sign(disclosure.binding_digest().as_bytes()).to_hex();
        disclosure
    }

    fn trust_selective_disclosure_verifier(state: &mut State) {
        let (_, oracle_id) = oracle_identity(9_121);
        state.oracle_set.insert(oracle_id);
    }

