    // --- Nonce enforcement edge cases (TDD Round 13, Lane B) ---
    //
    // These tests pin the nonce boundary behavior behind #688/#1002 so that any
    // future refactor that weakens replay protection will break loudly. They
    // exercise the BalanceTransfer nonce check at
    // `shared-protocol/src/blockchain/state.rs` (`apply_transition_inner`).

    /// Replay protection: once a BalanceTransfer at nonce=N is applied, a
    /// second transfer submitted with the same nonce=N MUST be rejected with
    /// `InvalidNonce`. The first tx's effects (balances) must remain, and the
    /// account nonce must stay at N+1 — i.e. the replay must leave state
    /// completely untouched beyond the already-applied first tx.
    #[test]
    fn nonce_rejects_replay_with_same_value() {
        let mut state = State::new();
        let from = addr(50);
        let to = addr(51);
        state.create_account(from, Balance::new(100));

        // First transfer at nonce=0 succeeds.
        state
            .apply_transition(StateTransition::BalanceTransfer {
                from,
                to,
                amount: Balance::new(10),
                nonce: Some(0),
                current_block:
                    crate::consensus::proof_of_publishing::NONCE_ENFORCEMENT_ACTIVATION_HEIGHT,
            })
            .expect("first transfer at nonce=0 should succeed");

        let sender_after_first = state.get_account(&from).expect("sender exists");
        assert_eq!(sender_after_first.nonce, 1);
        assert_eq!(sender_after_first.balance, Balance::new(90));
        let receiver_after_first = state.get_account(&to).expect("receiver exists");
        assert_eq!(receiver_after_first.balance, Balance::new(10));

        // Replay at nonce=0 must be rejected.
        let err = state
            .apply_transition(StateTransition::BalanceTransfer {
                from,
                to,
                amount: Balance::new(10),
                nonce: Some(0),
                current_block:
                    crate::consensus::proof_of_publishing::NONCE_ENFORCEMENT_ACTIVATION_HEIGHT,
            })
            .expect_err("replay at same nonce must be rejected");
        assert!(
            matches!(err, StateError::InvalidNonce),
            "expected InvalidNonce, got: {err:?}"
        );

        // State is unchanged by the rejected replay: nonce still 1, balances untouched.
        let sender_after_replay = state.get_account(&from).expect("sender still exists");
        assert_eq!(
            sender_after_replay.nonce, 1,
            "rejected replay must not bump nonce"
        );
        assert_eq!(
            sender_after_replay.balance,
            Balance::new(90),
            "rejected replay must not deduct balance"
        );
        assert_eq!(
            sender_after_replay.spendable_balance,
            Balance::new(90),
            "rejected replay must not deduct spendable_balance"
        );
        let receiver_after_replay = state.get_account(&to).expect("receiver still exists");
        assert_eq!(
            receiver_after_replay.balance,
            Balance::new(10),
            "rejected replay must not credit recipient"
        );
    }

    /// Gap rejection: submitting a future nonce (skipping intermediate values)
    /// must be rejected. After the gap is rejected, the sequential path
    /// nonce=0, 1, 2 must each succeed in order.
    #[test]
    fn nonce_rejects_gap_in_sequence() {
        let mut state = State::new();
        let from = addr(52);
        let to = addr(53);
        state.create_account(from, Balance::new(100));

        // Jumping to nonce=2 (skipping 0, 1) must be rejected.
        let err = state
            .apply_transition(StateTransition::BalanceTransfer {
                from,
                to,
                amount: Balance::new(5),
                nonce: Some(2),
                current_block:
                    crate::consensus::proof_of_publishing::NONCE_ENFORCEMENT_ACTIVATION_HEIGHT,
            })
            .expect_err("nonce gap must be rejected");
        assert!(
            matches!(err, StateError::InvalidNonce),
            "expected InvalidNonce for gap, got: {err:?}"
        );

        let sender = state.get_account(&from).expect("sender exists");
        assert_eq!(sender.nonce, 0, "rejected gap must not advance nonce");
        assert_eq!(
            sender.balance,
            Balance::new(100),
            "rejected gap must not deduct balance"
        );

        // Sequential nonces succeed: 0, 1, 2.
        for expected_nonce in 0u64..=2 {
            state
                .apply_transition(StateTransition::BalanceTransfer {
                    from,
                    to,
                    amount: Balance::new(5),
                    nonce: Some(expected_nonce),
                    current_block:
                        crate::consensus::proof_of_publishing::NONCE_ENFORCEMENT_ACTIVATION_HEIGHT,
                })
                .unwrap_or_else(|e| {
                    panic!(
                        "sequential transfer at nonce={expected_nonce} should succeed, got {e:?}"
                    )
                });
            let sender = state.get_account(&from).expect("sender exists");
            assert_eq!(
                sender.nonce,
                expected_nonce + 1,
                "nonce should advance by exactly 1 after each accepted transfer"
            );
        }

        // After 3 successful transfers of 5 each, balance = 100 - 15 = 85.
        let sender = state.get_account(&from).expect("sender exists");
        assert_eq!(sender.balance, Balance::new(85));
        assert_eq!(sender.nonce, 3);
        let receiver = state.get_account(&to).expect("receiver exists");
        assert_eq!(receiver.balance, Balance::new(15));
    }

    /// u64::MAX nonce boundary — pins the HARDENED behavior from TDD Round 14
    /// Lane B (#1147, #1149).
    ///
    /// Prior to #1147/#1149, a BalanceTransfer submitted with an account whose
    /// nonce was already `u64::MAX` would pass the nonce equality check, the
    /// balance deductions would be applied, and the post-deduction
    /// `sender.nonce += 1` would PANIC under `overflow-checks = true`, leaving
    /// the sender balance debited but the nonce never advanced — a
    /// consensus-critical partial state.
    ///
    /// The fix pre-computes the incremented nonce via `checked_add(1)` BEFORE
    /// any balance mutation, so that an overflow at the boundary returns a
    /// clean `StateError::NonceOverflow` with the account state fully
    /// unchanged.
    ///
    /// This test replaces the R13 Lane B `catch_unwind` pin that asserted the
    /// panic; it now asserts the tight error path. The helper test
    /// `nonce_overflow_does_not_panic_in_release_or_debug_profile` below
    /// additionally guards against someone reintroducing a raw `+= 1`.
    #[test]
    fn nonce_boundary_at_u64_max() {
        let mut state = State::new();
        let from = addr(54);
        let to = addr(55);
        state.create_account(from, Balance::new(100));
        // Seed the sender nonce at u64::MAX directly so the increment on success
        // would land on the overflow boundary.
        state.get_account_mut(&from).expect("sender exists").nonce = u64::MAX;

        let err = state
            .apply_transition(StateTransition::BalanceTransfer {
                from,
                to,
                amount: Balance::new(10),
                nonce: Some(u64::MAX),
                current_block:
                    crate::consensus::proof_of_publishing::NONCE_ENFORCEMENT_ACTIVATION_HEIGHT,
            })
            .expect_err(
                "transfer at nonce=u64::MAX must be rejected with NonceOverflow after #1147/#1149",
            );
        assert!(
            matches!(err, StateError::NonceOverflow),
            "expected StateError::NonceOverflow, got: {err:?}"
        );

        // The sender must be fully untouched: balance, spendable_balance, nonce.
        let sender = state.get_account(&from).expect("sender still exists");
        assert_eq!(
            sender.nonce,
            u64::MAX,
            "rejected overflow must not advance nonce"
        );
        assert_eq!(
            sender.balance,
            Balance::new(100),
            "rejected overflow must not debit balance"
        );
        assert_eq!(
            sender.spendable_balance,
            Balance::new(100),
            "rejected overflow must not debit spendable_balance"
        );
        // The recipient must never have been created.
        assert!(
            state.get_account(&to).is_none(),
            "rejected overflow must not create recipient account"
        );
    }

    /// Pinning test for #1147/#1149: a BalanceTransfer submitted with an
    /// account at `nonce = u64::MAX` must be rejected with
    /// `StateError::NonceOverflow` and MUST leave the sender's balance
    /// undebited. This guards the atomicity property of the fix — if a future
    /// refactor moves the balance debit back in front of the checked_add,
    /// this test will fail loudly.
    #[test]
    fn nonce_overflow_rejects_transaction_without_debiting_balance() {
        let mut state = State::new();
        let from = addr(60);
        let to = addr(61);
        state.create_account(from, Balance::new(1000));
        state.get_account_mut(&from).expect("sender exists").nonce = u64::MAX;

        let err = state
            .apply_transition(StateTransition::BalanceTransfer {
                from,
                to,
                amount: Balance::new(1),
                nonce: Some(u64::MAX),
                current_block:
                    crate::consensus::proof_of_publishing::NONCE_ENFORCEMENT_ACTIVATION_HEIGHT,
            })
            .expect_err("transaction at u64::MAX nonce must be rejected");
        assert!(
            matches!(err, StateError::NonceOverflow),
            "expected NonceOverflow, got: {err:?}"
        );

        let sender = state.get_account(&from).expect("sender still exists");
        assert_eq!(
            sender.balance,
            Balance::new(1000),
            "balance must not be debited on overflow rejection"
        );
        assert_eq!(
            sender.spendable_balance,
            Balance::new(1000),
            "spendable_balance must not be debited on overflow rejection"
        );
        assert_eq!(
            sender.nonce,
            u64::MAX,
            "nonce must not be advanced on overflow rejection"
        );
        assert!(
            state.get_account(&to).is_none(),
            "recipient must not be created on overflow rejection"
        );
    }

    /// Pinning test for #1147/#1149: the two transfers leading up to the
    /// overflow boundary must succeed normally (nonce = u64::MAX - 2 →
    /// u64::MAX - 1 → u64::MAX), and only the third transfer — which would
    /// carry the nonce past u64::MAX — must be rejected with
    /// `StateError::NonceOverflow` while leaving state unchanged.
    #[test]
    fn nonce_increments_normally_below_overflow_boundary() {
        let mut state = State::new();
        let from = addr(62);
        let to = addr(63);
        state.create_account(from, Balance::new(1000));
        state.get_account_mut(&from).expect("sender exists").nonce = u64::MAX - 2;

        // First transfer: nonce goes from u64::MAX - 2 to u64::MAX - 1.
        state
            .apply_transition(StateTransition::BalanceTransfer {
                from,
                to,
                amount: Balance::new(10),
                nonce: Some(u64::MAX - 2),
                current_block:
                    crate::consensus::proof_of_publishing::NONCE_ENFORCEMENT_ACTIVATION_HEIGHT,
            })
            .expect("first transfer near boundary should succeed");
        assert_eq!(
            state.get_account(&from).expect("sender exists").nonce,
            u64::MAX - 1,
        );
        assert_eq!(
            state.get_account(&from).expect("sender exists").balance,
            Balance::new(990),
        );

        // Second transfer: nonce goes from u64::MAX - 1 to u64::MAX.
        state
            .apply_transition(StateTransition::BalanceTransfer {
                from,
                to,
                amount: Balance::new(10),
                nonce: Some(u64::MAX - 1),
                current_block:
                    crate::consensus::proof_of_publishing::NONCE_ENFORCEMENT_ACTIVATION_HEIGHT,
            })
            .expect("second transfer near boundary should succeed");
        assert_eq!(
            state.get_account(&from).expect("sender exists").nonce,
            u64::MAX,
        );
        assert_eq!(
            state.get_account(&from).expect("sender exists").balance,
            Balance::new(980),
        );

        // Third transfer: nonce would overflow — must be rejected.
        let err = state
            .apply_transition(StateTransition::BalanceTransfer {
                from,
                to,
                amount: Balance::new(10),
                nonce: Some(u64::MAX),
                current_block:
                    crate::consensus::proof_of_publishing::NONCE_ENFORCEMENT_ACTIVATION_HEIGHT,
            })
            .expect_err("third transfer at u64::MAX must be rejected");
        assert!(
            matches!(err, StateError::NonceOverflow),
            "expected NonceOverflow on third transfer, got: {err:?}"
        );

        // State after rejected third transfer: nonce still u64::MAX, balance
        // unchanged from after the second transfer (980, not 970).
        let sender = state.get_account(&from).expect("sender exists");
        assert_eq!(
            sender.nonce,
            u64::MAX,
            "rejected overflow must not advance nonce past u64::MAX"
        );
        assert_eq!(
            sender.balance,
            Balance::new(980),
            "rejected overflow must not debit balance"
        );
    }

    /// Regression guard for #1147/#1149: directly invoking
    /// `apply_transition_inner` with a `u64::MAX` nonce account MUST return
    /// `Err(StateError::NonceOverflow)` and MUST NOT panic under
    /// `overflow-checks = true` (which is enabled on all workspace profiles:
    /// `dev`, `test`, `release`, `release-checked`). If someone reintroduces
    /// a raw `nonce += 1` in `apply_transition_inner`, this test will fail by
    /// unwinding instead of returning a `Result`.
    #[test]
    fn nonce_overflow_does_not_panic_in_release_or_debug_profile() {
        use std::panic::{AssertUnwindSafe, catch_unwind};

        let mut state = State::new();
        let from = addr(64);
        let to = addr(65);
        state.create_account(from, Balance::new(500));
        state.get_account_mut(&from).expect("sender exists").nonce = u64::MAX;

        let result = catch_unwind(AssertUnwindSafe(|| {
            state.apply_transition(StateTransition::BalanceTransfer {
                from,
                to,
                amount: Balance::new(1),
                nonce: Some(u64::MAX),
                current_block:
                    crate::consensus::proof_of_publishing::NONCE_ENFORCEMENT_ACTIVATION_HEIGHT,
            })
        }));

        // Must NOT panic — must return a clean Err.
        let apply_result = result
            .expect("apply_transition must not panic on nonce overflow (regression guard)");
        let err = apply_result.expect_err("apply_transition must return Err on nonce overflow");
        assert!(
            matches!(err, StateError::NonceOverflow),
            "expected StateError::NonceOverflow, got: {err:?}"
        );
    }

    /// First-use on a newly created account: an account that came into
    /// existence purely as a recipient of a prior transfer should start with
    /// nonce=0, and its first outgoing transfer at nonce=0 must succeed and
    /// leave the account with nonce=1. This exercises the "account created
    /// implicitly as recipient" path that the replay/gap tests do not cover.
    #[test]
    fn nonce_first_use_on_new_account() {
        let mut state = State::new();
        let funder = addr(56);
        let new_sender = addr(57); // does not exist in state yet
        let final_recipient = addr(58);
        state.create_account(funder, Balance::new(100));

        // Fund the new_sender by a transfer from funder. This implicitly
        // creates new_sender via `create_account` inside the transfer path.
        state
            .apply_transition(StateTransition::BalanceTransfer {
                from: funder,
                to: new_sender,
                amount: Balance::new(25),
                nonce: Some(0),
                current_block:
                    crate::consensus::proof_of_publishing::NONCE_ENFORCEMENT_ACTIVATION_HEIGHT,
            })
            .expect("funding transfer should succeed");

        // The newly created sender account should exist with nonce=0 and full balance.
        let new_sender_before = state
            .get_account(&new_sender)
            .expect("new_sender should have been created as recipient");
        assert_eq!(
            new_sender_before.nonce, 0,
            "implicitly created account should start with nonce=0"
        );
        assert_eq!(new_sender_before.balance, Balance::new(25));
        assert_eq!(new_sender_before.spendable_balance, Balance::new(25));

        // First outgoing transfer FROM the new sender at its genesis nonce=0.
        state
            .apply_transition(StateTransition::BalanceTransfer {
                from: new_sender,
                to: final_recipient,
                amount: Balance::new(10),
                nonce: Some(0),
                current_block:
                    crate::consensus::proof_of_publishing::NONCE_ENFORCEMENT_ACTIVATION_HEIGHT,
            })
            .expect("first outgoing transfer from new account at nonce=0 should succeed");

        // Post-conditions: new_sender nonce=1, balance=15; recipient has 10.
        let new_sender_after = state.get_account(&new_sender).expect("new_sender exists");
        assert_eq!(
            new_sender_after.nonce, 1,
            "nonce must be 1 after first outgoing transfer"
        );
        assert_eq!(new_sender_after.balance, Balance::new(15));
        assert_eq!(new_sender_after.spendable_balance, Balance::new(15));

        let final_recipient_acct = state
            .get_account(&final_recipient)
            .expect("final recipient should have been created");
        assert_eq!(final_recipient_acct.balance, Balance::new(10));
        assert_eq!(
            final_recipient_acct.nonce, 0,
            "recipient-only account should still have nonce=0"
        );
    }

