    fn signed_confidential_transfer_payload() -> ConfidentialTransferPayload {
        let keypairs = (0..8).map(|_| random_keypair()).collect::<Vec<_>>();
        let (signer_sk, _) = keypairs[0];
        let decoys = keypairs[1..]
            .iter()
            .map(|(_, public_key)| RingMember {
                public_key: *public_key,
            })
            .collect::<Vec<_>>();
        let key_image = KeyImage::generate(&signer_sk).expect("key image");
        let mut payload = ConfidentialTransferPayload {
            output_commitments: vec!["61".repeat(32)],
            range_proof: Some("62".repeat(32)),
            stealth_data: Some("63".repeat(32)),
            ring_signature: None,
            key_images: vec![hex::encode(key_image.to_bytes())],
            encrypted_payload: Some("64".repeat(32)),
            privacy_level: crate::blockchain::transaction::PrivacyLevel::High,
            selective_disclosures: Vec::new(),
            signed_message: None,
        };
        let signed_message = payload.authorization_message();
        let signature =
            MLSAGSignature::sign(&signed_message, &signer_sk, &decoys).expect("ring signature");
        payload.ring_signature = Some(hex::encode(
            serde_json::to_vec(&signature).expect("serialize ring signature"),
        ));
        payload.signed_message = Some(hex::encode(signed_message));
        payload
    }

