    #[test]
    fn governance_transitions_for_block_drops_unapplyable_transfer_loudly() {
        // #2056 regression: a transparent Transfer admitted to the mempool but
        // that fails to apply during block assembly must be (a) excluded from
        // the returned transition set and (b) counted on `tx_dropped_total` —
        // instead of vanishing silently as it did before this fix (no log, no
        // metric). We use an authorization failure (opt-out set but no signing
        // key), the same failure class that swallowed the faucet transfer.
        let mut state = State::new();
        let from = addr(70);
        let to = addr(71);
        state.create_account(from, Balance::new(1_000));

        let mut tx = Transaction::new(
            vec![],
            vec![crate::blockchain::transaction::TransactionOutput {
                amount: 0,
                address: from.to_string(),
                script: "OP_TRUE".to_string(),
                nft_data: None,
            }],
        );
        tx.sender_address = from;
        tx.tx_type = TransactionType::Transfer;
        tx.data = Some(
            serde_json::to_string(&TransparentTransferPayload {
                from: from.to_string(),
                to: to.to_string(),
                amount: 10,
                transparent_opt_out: true,
                opt_out_audit_tag: None,
                // No embedded authorization => verify_authorization() fails =>
                // StateError::Privacy => tx_drop_reason() == "privacy_rejected".
                auth_pubkey: None,
                auth_signature: None,
                authority: None,
                authority_signature: None,
                passkey_auth: None,
                sponsorship: None,
                session_key_auth: None,
            })
            .unwrap(),
        );
        tx.set_id();

        // CORE_METRICS is a process-global singleton shared across tests, so we
        // assert on a delta rather than an absolute value.
        let before = CORE_METRICS
            .tx_dropped_total
            .with_label_values(&["privacy_rejected"])
            .get();

        let transitions = state.governance_transitions_for_block(&[tx], 5, 1_700_000_000);

        // (a) the unapplyable transfer is excluded from the block's transitions
        // (a fresh State has no governance-due proposals, so the vec is empty).
        assert!(
            transitions.is_empty(),
            "expected the unapplyable transfer to be excluded, got {transitions:?}"
        );

        // (b) the drop is now observable on the rejection counter.
        let after = CORE_METRICS
            .tx_dropped_total
            .with_label_values(&["privacy_rejected"])
            .get();
        assert_eq!(
            after - before,
            1,
            "tx_dropped_total{{reason=privacy_rejected}} must increment by exactly 1"
        );
    }

