    /// #3214 helper for the feature-gate tests below: commit and reveal one
    /// physically impossible weather reading (200 °C) for `station_id`,
    /// returning the reveal's result.
    fn apply_data_quality_violation_reveal(
        state: &mut State,
        station_id: &str,
        nonce: &str,
        timestamp: i64,
    ) -> Result<(), StateError> {
        let data = serde_json::json!({"temperature": 200.0, "humidity": 50.0});
        let contribution_type = "weather";
        let commit_id =
            Transaction::compute_commit_id(&data, nonce, station_id, timestamp, contribution_type);
        state
            .apply_transition(StateTransition::RegisterCommit {
                payload: CommitPayload {
                    commit_id: commit_id.clone(),
                    station_id: station_id.to_string(),
                    timestamp,
                    contribution_type: contribution_type.to_string(),
                    auth_pubkey: None,
                    auth_signature: None,
                },
                block_height: 10,
            })
            .unwrap();
        state.apply_transition(StateTransition::ApplyReveal {
            payload: RevealPayload {
                commit_id,
                station_id: station_id.to_string(),
                timestamp,
                contribution_type: contribution_type.to_string(),
                data,
                nonce: nonce.to_string(),
                data_cid: None,
                data_hash: None,
                storage_provider: None,
                provenance: None,
                manifest: None,
                verification_receipt: None,
                compute_receipt: None,
                quality_tier: None,
            },
            block_height: 11,
            block_timestamp: 0,
        })
    }

    /// #3214 feature OFF (the lib test binary installs no feature schedule,
    /// exactly like the live v1 testnet): a data-quality violation keeps the
    /// pre-#3214 slashing target. The trigger's identity is still the
    /// `station_id` placeholder even though the station has a registered,
    /// funded, parseable owner, and finalization debits nobody: the owner's
    /// balance, reputation and cooldown are untouched. Deleting the
    /// `StationOwnerSlashIdentity` gate turns this RED.
    #[test]
    fn apply_reveal_data_quality_slash_keeps_station_id_target_while_owner_binding_unscheduled() {
        use crate::crypto::chain_binding::{ConsensusFeature, feature_active};
        assert!(!feature_active(ConsensusFeature::StationOwnerSlashIdentity, 11));
        assert!(!feature_active(ConsensusFeature::StationOwnerSlashIdentity, u64::MAX));

        let mut state = State::new();
        let station_id = "station-dq-off";
        let (_, owner_public_key, owner) = governance_voter(3_214);
        state.create_account(owner, Balance::new(100));
        let mut station = weather_station_with_elevation(station_id, None);
        station.owner_address = owner_public_key.to_address();
        state.station_registry.register(station).unwrap();
        state.oracle_set.insert(owner.to_string());
        state.oracle_registry.apply_reputation_event(ReputationEvent {
            oracle_id: owner.to_string(),
            delta: 50,
            reason: "seed".to_string(),
            timestamp: 0,
        });
        let reputation_before = state.oracle_registry.reputation_score(&owner.to_string());

        let result =
            apply_data_quality_violation_reveal(&mut state, station_id, "nonce-dq-off", 1_700_000_000);

        assert!(
            matches!(
                result,
                Err(StateError::SlashingTriggered(
                    crate::oracle::attestation::SlashingTrigger::DataQualityViolation {
                        ref oracle_id,
                        ..
                    }
                )) if oracle_id == station_id
            ),
            "unscheduled: the trigger must keep the pre-#3214 station_id identity, got: {result:?}"
        );
        assert_eq!(state.deferred_slashing_triggers.len(), 1);
        assert!(matches!(
            &state.deferred_slashing_triggers[0].0,
            crate::oracle::attestation::SlashingTrigger::DataQualityViolation { oracle_id, .. }
                if oracle_id == station_id
        ));

        state.flush_deferred_slashing();
        let account = state.get_account(&owner).unwrap();
        assert_eq!(account.balance, Balance::new(100), "unscheduled: the owner is never debited");
        assert_eq!(account.spendable_balance, Balance::new(100));
        assert_eq!(
            state.oracle_registry.reputation_score(&owner.to_string()),
            reputation_before,
            "unscheduled: the owner's reputation is untouched"
        );
        assert!(
            !state.oracle_registry.is_in_cooldown(&owner.to_string(), 12),
            "unscheduled: the owner is never put in cooldown"
        );
    }

    /// #3214 feature OFF: an unregistered station still produces the
    /// pre-#3214 `SlashingTriggered` result with the `station_id` identity.
    /// The activated fail-closed `SlashingApplication` must not leak into the
    /// unscheduled path.
    #[test]
    fn apply_reveal_unregistered_station_keeps_pre_3214_result_while_owner_binding_unscheduled() {
        let mut state = State::new();
        let station_id = "station-dq-off-unregistered";
        let result = apply_data_quality_violation_reveal(
            &mut state,
            station_id,
            "nonce-dq-off-unregistered",
            1_700_000_001,
        );
        assert!(
            matches!(
                result,
                Err(StateError::SlashingTriggered(
                    crate::oracle::attestation::SlashingTrigger::DataQualityViolation {
                        ref oracle_id,
                        ..
                    }
                )) if oracle_id == station_id
            ),
            "unscheduled: an unregistered station keeps the pre-#3214 result, got: {result:?}"
        );
        assert_eq!(state.deferred_slashing_triggers.len(), 1);
    }

    /// #3214: `station_slash_identity` (used only once
    /// `StationOwnerSlashIdentity` is active) resolves the canonical `wrf…`
    /// and internal `0x…` owner forms to one `0x…` identity, and fails closed
    /// for an unregistered station, a non-address owner and an unfunded owner.
    #[test]
    fn station_slash_identity_resolves_canonical_owner_and_fails_closed() {
        let mut state = State::new();
        let (_, owner_public_key, owner) = governance_voter(3_215);
        state.create_account(owner, Balance::new(100));

        let mut wrf = weather_station_with_elevation("station-wrf", None);
        wrf.owner_address = owner_public_key.to_address();
        assert!(wrf.owner_address.starts_with("wrf"));
        state.station_registry.register(wrf).unwrap();
        let mut hex = weather_station_with_elevation("station-hex", None);
        hex.owner_address = owner.to_string();
        state.station_registry.register(hex).unwrap();
        state
            .station_registry
            .register(weather_station_with_elevation("station-bad", None))
            .unwrap();
        let mut unfunded = weather_station_with_elevation("station-unfunded", None);
        unfunded.owner_address = addr(202).to_string();
        state.station_registry.register(unfunded).unwrap();

        assert_eq!(state.station_slash_identity("station-wrf").unwrap(), owner.to_string());
        assert_eq!(state.station_slash_identity("station-hex").unwrap(), owner.to_string());
        for (station_id, needle) in [
            ("station-missing", "unregistered station"),
            ("station-bad", "not a slashable account address"),
            ("station-unfunded", "has no on-chain account"),
        ] {
            let result = state.station_slash_identity(station_id);
            assert!(
                matches!(result, Err(StateError::SlashingApplication(ref m)) if m.contains(needle)),
                "{station_id}: expected SlashingApplication containing {needle:?}, got {result:?}"
            );
        }
    }

