    #[test]
    fn state_root_includes_contract_code_and_storage() {
        // Different code -> different root
        let mut state_a = State::new();
        let mut state_b = State::new();
        let contract_addr = addr(99);
        {
            let acct = state_a.create_account(contract_addr, Balance::new(0));
            acct.is_contract = true;
            acct.code = Some(vec![0xDE, 0xAD]);
        }
        {
            let acct = state_b.create_account(contract_addr, Balance::new(0));
            acct.is_contract = true;
            acct.code = Some(vec![0xBE, 0xEF]);
        }
        state_a.recalculate_state_root();
        state_b.recalculate_state_root();
        assert_ne!(
            state_a.state_root, state_b.state_root,
            "different code must produce different state roots"
        );

        // Different storage -> different root
        let mut state_c = State::new();
        let mut state_d = State::new();
        let code = vec![0x60, 0x00];
        {
            let acct = state_c.create_account(contract_addr, Balance::new(0));
            acct.is_contract = true;
            acct.code = Some(code.clone());
            acct.storage.insert(vec![0x01], vec![0xAA]);
        }
        {
            let acct = state_d.create_account(contract_addr, Balance::new(0));
            acct.is_contract = true;
            acct.code = Some(code.clone());
            acct.storage.insert(vec![0x01], vec![0xBB]);
        }
        state_c.recalculate_state_root();
        state_d.recalculate_state_root();
        assert_ne!(
            state_c.state_root, state_d.state_root,
            "different storage values must produce different state roots"
        );

        // Identical code + storage -> identical root (storage insertion order must not matter)
        let mut state_e = State::new();
        let mut state_f = State::new();
        {
            let acct = state_e.create_account(contract_addr, Balance::new(0));
            acct.is_contract = true;
            acct.code = Some(code.clone());
            acct.storage.insert(vec![0x01], vec![0xAA]);
            acct.storage.insert(vec![0x02], vec![0xBB]);
        }
        {
            let acct = state_f.create_account(contract_addr, Balance::new(0));
            acct.is_contract = true;
            acct.code = Some(code.clone());
            // Insert in reverse key order — must still hash identically
            acct.storage.insert(vec![0x02], vec![0xBB]);
            acct.storage.insert(vec![0x01], vec![0xAA]);
        }
        state_e.recalculate_state_root();
        state_f.recalculate_state_root();
        assert_eq!(
            state_e.state_root, state_f.state_root,
            "identical code+storage with different insertion order must produce identical root"
        );

        // Determinism: recalculating twice gives same result
        state_e.recalculate_state_root();
        assert_eq!(
            state_e.state_root, state_f.state_root,
            "recalculating the same state must be byte-identical"
        );
    }

    #[test]
    fn state_root_none_code_equals_initial() {
        // An account that had code set and then cleared back to None must hash
        // identically to an account that was always code: None with empty storage.
        // This locks in the "empty code tag contributes nothing asymmetric" invariant.
        let account_addr = addr(77);

        let mut state_a = State::new();
        state_a.create_account(account_addr, Balance::new(0));
        state_a.recalculate_state_root();

        let mut state_b = State::new();
        {
            let acct = state_b.create_account(account_addr, Balance::new(0));
            acct.code = Some(vec![0xDE, 0xAD]);
        }
        // Mutate back to None (same path a contract self-destruct / clear would take).
        state_b.accounts.get_mut(&account_addr).unwrap().code = None;
        state_b.recalculate_state_root();

        assert_eq!(
            state_a.state_root, state_b.state_root,
            "empty code tag must contribute nothing asymmetric"
        );
    }

    #[test]
    fn state_root_storage_btreemap_deterministic_order() {
        // Verify that BTreeMap storage field maintains determinism:
        // random insertion order produces identical state roots to sorted insertion.
        // This test ensures the migration from FxHashMap (with explicit sort) to
        // BTreeMap (with structural ordering) produces byte-identical roots.
        let contract_addr = addr(88);
        let code = vec![0x60, 0x00, 0x60, 0x01];

        // State with random insertion order
        let mut state_random = State::new();
        {
            let acct = state_random.create_account(contract_addr, Balance::new(100));
            acct.is_contract = true;
            acct.code = Some(code.clone());
            // Insert storage in random order
            acct.storage.insert(vec![0x05], vec![0xEE]);
            acct.storage.insert(vec![0x01], vec![0xAA]);
            acct.storage.insert(vec![0x03], vec![0xCC]);
            acct.storage.insert(vec![0x02], vec![0xBB]);
            acct.storage.insert(vec![0x04], vec![0xDD]);
        }
        state_random.recalculate_state_root();

        // State with sorted insertion order
        let mut state_sorted = State::new();
        {
            let acct = state_sorted.create_account(contract_addr, Balance::new(100));
            acct.is_contract = true;
            acct.code = Some(code.clone());
            // Insert storage in sorted order
            acct.storage.insert(vec![0x01], vec![0xAA]);
            acct.storage.insert(vec![0x02], vec![0xBB]);
            acct.storage.insert(vec![0x03], vec![0xCC]);
            acct.storage.insert(vec![0x04], vec![0xDD]);
            acct.storage.insert(vec![0x05], vec![0xEE]);
        }
        state_sorted.recalculate_state_root();

        assert_eq!(
            state_random.state_root, state_sorted.state_root,
            "BTreeMap storage must produce identical roots regardless of insertion order"
        );

        // Verify recalculation is byte-identical (determinism check)
        state_random.recalculate_state_root();
        assert_eq!(
            state_random.state_root, state_sorted.state_root,
            "recalculating storage root must be byte-identical"
        );
    }

