    /// Regression test for #1844: oracle attestation with nonce=None must be rejected, not
    /// silently passed through. Also verifies replay of a captured attestation is blocked.
    #[test]
    fn oracle_attestation_nonce_none_bypasses_guard_regression() {
        let mut state = State::new();
        let (oracle_sk, oracle_id) = oracle_identity(200);
        state
            .apply_transition(StateTransition::SetOracleConfig {
                oracle_set: vec![oracle_id.clone()],
                oracle_quorum: 1,
            })
            .unwrap();

        // 1. nonce=None must be a hard error (was silently passed before #1844 fix).
        let payload_no_nonce = {
            let mut p = OracleAttestationPayload {
                commit_id: "commit-replay-test".to_string(),
                oracle_id: oracle_id.clone(),
                approved: true,
                signature: None,
                confidence: Some(0.9),
                timestamp: 1000,
                nonce: None,
            };
            p.signature = Some(oracle_sk.sign(p.signing_message().as_bytes()).to_string());
            p
        };
        let err = state
            .apply_transition(StateTransition::RecordOracleAttestation {
                payload: payload_no_nonce,
                current_block: 1,
            })
            .expect_err("nonce=None must be rejected");
        assert!(
            matches!(err, StateError::MissingOracleNonce),
            "expected MissingOracleNonce, got: {err:?}"
        );

        // 2. A captured attestation with a valid nonce must be accepted once.
        let payload_with_nonce = {
            let mut p = OracleAttestationPayload {
                commit_id: "commit-replay-test".to_string(),
                oracle_id: oracle_id.clone(),
                approved: true,
                signature: None,
                confidence: Some(0.9),
                timestamp: 1000,
                nonce: Some("unique-nonce-abc123".to_string()),
            };
            p.signature = Some(oracle_sk.sign(p.signing_message().as_bytes()).to_string());
            p
        };
        state
            .apply_transition(StateTransition::RecordOracleAttestation {
                payload: payload_with_nonce.clone(),
                current_block: 1,
            })
            .expect("first submission with valid nonce must succeed");

        // 3. Replay of the same captured attestation must be rejected.
        let replay_err = state
            .apply_transition(StateTransition::RecordOracleAttestation {
                payload: payload_with_nonce,
                current_block: 2,
            })
            .expect_err("replay of the same nonce must be rejected");
        assert!(
            matches!(replay_err, StateError::DuplicateOracleNonce),
            "expected DuplicateOracleNonce on replay, got: {replay_err:?}"
        );
    }

    /// #2031: the nonce guard rejects an *empty-string* nonce, not just
    /// `nonce=None`. This is a distinct branch — `.filter(|n| !n.is_empty())`
    /// in `RecordOracleAttestation` — that the #1844 regression test (which
    /// only exercises `nonce=None`) does not cover. An empty nonce must map to
    /// `MissingOracleNonce` and must not mutate attestation state.
    #[test]
    fn oracle_attestation_rejects_empty_string_nonce() {
        let mut state = State::new();
        let (oracle_sk, oracle_id) = oracle_identity(220);
        state
            .apply_transition(StateTransition::SetOracleConfig {
                oracle_set: vec![oracle_id.clone()],
                oracle_quorum: 1,
            })
            .unwrap();

        let payload = {
            let mut p = OracleAttestationPayload {
                commit_id: "commit-empty-nonce".to_string(),
                oracle_id: oracle_id.clone(),
                approved: true,
                signature: None,
                confidence: Some(0.9),
                timestamp: 1000,
                nonce: Some(String::new()), // empty, not None
            };
            p.signature = Some(oracle_sk.sign(p.signing_message().as_bytes()).to_string());
            p
        };
        let err = state
            .apply_transition(StateTransition::RecordOracleAttestation {
                payload,
                current_block: 1,
            })
            .expect_err("empty-string nonce must be rejected");
        assert!(
            matches!(err, StateError::MissingOracleNonce),
            "expected MissingOracleNonce for empty nonce, got: {err:?}"
        );
        // The rejected attestation must not have been recorded.
        assert!(
            !state.attestations.contains_key("commit-empty-nonce"),
            "rejected empty-nonce attestation must not mutate attestation state"
        );
        assert!(
            state.spent_oracle_nonces.is_empty(),
            "no nonce should be marked spent for a rejected attestation"
        );
    }

    /// #2031: a replayed (duplicate-nonce) attestation must be rejected with
    /// `DuplicateOracleNonce` *and* leave attestation/quorum state untouched.
    /// Complements the #1844 test, which asserts the rejection but not that the
    /// second submission is a no-op on chain state.
    #[test]
    fn oracle_attestation_duplicate_nonce_does_not_mutate_state() {
        let mut state = State::new();
        let (oracle_sk, oracle_id) = oracle_identity(221);
        state
            .apply_transition(StateTransition::SetOracleConfig {
                oracle_set: vec![oracle_id.clone()],
                oracle_quorum: 1,
            })
            .unwrap();

        let payload = signed_attestation(&oracle_sk, &oracle_id, "commit-dup", true, 0.9, 1000);
        let nonce = payload.nonce.clone().unwrap();
        state
            .apply_transition(StateTransition::RecordOracleAttestation {
                payload,
                current_block: 1,
            })
            .expect("first attestation must succeed");
        let approvals_before = state.attestations["commit-dup"].approvals();
        let spent_before = state.spent_oracle_nonces.len();
        assert!(state.spent_oracle_nonces.contains(&nonce));

        // Identical inputs → identical nonce + signature → a replay.
        let replay = signed_attestation(&oracle_sk, &oracle_id, "commit-dup", true, 0.9, 1000);
        let err = state
            .apply_transition(StateTransition::RecordOracleAttestation {
                payload: replay,
                current_block: 2,
            })
            .expect_err("replayed nonce must be rejected");
        assert!(
            matches!(err, StateError::DuplicateOracleNonce),
            "expected DuplicateOracleNonce, got: {err:?}"
        );
        assert_eq!(
            state.attestations["commit-dup"].approvals(),
            approvals_before,
            "rejected replay must not add an approval"
        );
        assert_eq!(
            state.spent_oracle_nonces.len(),
            spent_before,
            "rejected replay must not record another spent nonce"
        );
    }

    /// #2031: end-to-end recording + pruning through the public
    /// `apply_block_finalization` entry point (which calls `prune_expired_state`).
    /// Existing pruning tests insert into `spent_oracle_nonces` directly; this
    /// drives the real oracle-attestation path and the finalization boundary,
    /// confirming the replay window stays closed within the retention window
    /// and reopens only after the nonce is pruned.
    #[test]
    fn oracle_attestation_spent_nonce_recorded_and_pruned_via_finalization() {
        use crate::consensus::proof_of_publishing::DEFAULT_STATE_PRUNING_RETENTION_BLOCKS;

        let mut state = State::new();
        let (oracle_sk, oracle_id) = oracle_identity(222);
        state
            .apply_transition(StateTransition::SetOracleConfig {
                oracle_set: vec![oracle_id.clone()],
                oracle_quorum: 1,
            })
            .unwrap();

        let record_height = 5u64;
        let payload = signed_attestation(&oracle_sk, &oracle_id, "commit-prune", true, 0.9, 1000);
        let nonce = payload.nonce.clone().unwrap();
        state
            .apply_transition(StateTransition::RecordOracleAttestation {
                payload,
                current_block: record_height,
            })
            .expect("attestation must succeed");

        // (1) Nonce is recorded with its block height after a successful apply.
        assert!(state.spent_oracle_nonces.contains(&nonce));
        assert_eq!(
            state.spent_oracle_nonces_height.get(&nonce).copied(),
            Some(record_height),
        );

        // (2) Finalize *within* the retention window (cutoff == record_height,
        //     which retains entries at exactly that height): nonce retained and
        //     the guard still rejects a replay.
        state.apply_block_finalization(DEFAULT_STATE_PRUNING_RETENTION_BLOCKS + record_height);
        assert!(
            state.spent_oracle_nonces.contains(&nonce),
            "nonce within the retention window must be retained"
        );
        let replay = signed_attestation(&oracle_sk, &oracle_id, "commit-prune", true, 0.9, 1000);
        let replay_err = state
            .apply_transition(StateTransition::RecordOracleAttestation {
                payload: replay,
                current_block: DEFAULT_STATE_PRUNING_RETENTION_BLOCKS + record_height,
            })
            .expect_err("replay must still be blocked while the nonce is retained");
        assert!(matches!(replay_err, StateError::DuplicateOracleNonce));

        // (3) Finalize *past* retention (cutoff == record_height + 1, which
        //     prunes the height-record_height entry): nonce and its height are
        //     removed from state.
        state.apply_block_finalization(DEFAULT_STATE_PRUNING_RETENTION_BLOCKS + record_height + 1);
        assert!(
            !state.spent_oracle_nonces.contains(&nonce),
            "nonce must be pruned once past the retention window"
        );
        assert!(
            !state.spent_oracle_nonces_height.contains_key(&nonce),
            "nonce height record must be pruned too"
        );
    }

