    #[test]
    fn governance_parameter_update_changes_oracle_quorum() {
        let mut state = State::new();
        let proposer = addr(8);
        let (_oracle_q1_sk, oracle_q1_id) = oracle_identity(301);
        let (_oracle_q2_sk, oracle_q2_id) = oracle_identity(302);
        let (_oracle_q3_sk, oracle_q3_id) = oracle_identity(303);
        let (sk, pk, voter) = governance_voter(9001);
        state.create_account(proposer, Balance::new(10_000));
        fund_governance_voter(&mut state, voter, 10);
        state
            .apply_transition(StateTransition::SetOracleConfig {
                oracle_set: vec![oracle_q1_id, oracle_q2_id, oracle_q3_id],
                oracle_quorum: 2,
            })
            .unwrap();

        let mut proposal_tx = Transaction::new(
            vec![],
            vec![crate::blockchain::transaction::TransactionOutput {
                amount: 0,
                address: "0x1111111111111111111111111111111111111111".to_string(),
                script: "OP_TRUE".to_string(),
                nft_data: None,
            }],
        );
        proposal_tx.sender_address = proposer;
        proposal_tx.tx_type = TransactionType::GovernanceProposal;
        proposal_tx.data = Some(
            serde_json::to_string(&GovernanceProposalPayload {
                proposal_id: "p1".to_string(),
                parameter: "oracle_quorum".to_string(),
                value: "3".to_string(),
                voting_deadline: Some(3),
                deposit: Some(GOVERNANCE_DEFAULT_DEPOSIT),
            })
            .unwrap(),
        );
        proposal_tx.set_id();

        state
            .apply_transition(StateTransition::ProcessGovernanceTransaction {
                tx: proposal_tx,
                current_block: 1,
            })
            .unwrap();

        let mut vote_tx = Transaction::new(
            vec![],
            vec![crate::blockchain::transaction::TransactionOutput {
                amount: 0,
                address: "0x2222222222222222222222222222222222222222".to_string(),
                script: "OP_TRUE".to_string(),
                nft_data: None,
            }],
        );
        vote_tx.sender_address = voter;
        vote_tx.tx_type = TransactionType::GovernanceVote;
        vote_tx.data = Some(signed_vote_json("p1", true, Some(10), &sk, &pk));
        vote_tx.set_id();

        state
            .apply_transition(StateTransition::ProcessGovernanceTransaction {
                tx: vote_tx,
                current_block: 2,
            })
            .unwrap();

        state
            .apply_transition(StateTransition::FinalizeGovernanceProposal {
                proposal_id: "p1".to_string(),
                current_block: 4,
                current_timestamp: 4,
            })
            .unwrap();

        assert_eq!(state.oracle_quorum, 3);
        assert_eq!(state.governance.params.oracle_quorum, 3);
        let proposal = state.governance.proposals.get("p1").unwrap();
        assert_eq!(proposal.status, GovernanceProposalStatus::Executed);
        assert_eq!(proposal.finalized_at_block, Some(4));
    }

    /// #2229 live-path coverage: exercise the `TransactionType::GovernanceVote`
    /// apply branch (`verify_vote_signature_at_height` gate) end-to-end at V1 —
    /// the unscheduled default — not just the payload method in isolation. A
    /// valid legacy `governance-vote-v1|<id>|<approve>` signature must be
    /// ACCEPTED (pre-cut compatibility), and a signature that does not verify
    /// must be REJECTED with "Invalid governance vote signature".
    /// Guard-revert: neutering the verification call in the vote branch turns
    /// the negative half GREEN-should-be-RED, so this is non-vacuous.
    #[test]
    fn governance_vote_apply_v1_accepts_legacy_and_rejects_bad_signature_2229() {
        fn gov_tx(sender: Address, tx_type: TransactionType, data: String) -> Transaction {
            let mut tx = Transaction::new(
                vec![],
                vec![crate::blockchain::transaction::TransactionOutput {
                    amount: 0,
                    address: "0x9999999999999999999999999999999999999999".to_string(),
                    script: "OP_TRUE".to_string(),
                    nft_data: None,
                }],
            );
            tx.sender_address = sender;
            tx.tx_type = tx_type;
            tx.data = Some(data);
            tx.set_id();
            tx
        }

        let mut state = State::new();
        let proposer = addr(21);
        let (sk_good, pk_good, voter_good) = governance_voter(22291);
        let (sk_bad, pk_bad, voter_bad) = governance_voter(22292);
        state.create_account(proposer, Balance::new(10_000));
        // Both voters funded BEFORE the proposal so each is in its voting-power snapshot.
        fund_governance_voter(&mut state, voter_good, 10);
        fund_governance_voter(&mut state, voter_bad, 10);

        let proposal = gov_tx(
            proposer,
            TransactionType::GovernanceProposal,
            serde_json::to_string(&GovernanceProposalPayload {
                proposal_id: "vp1".to_string(),
                parameter: "oracle_quorum".to_string(),
                value: "3".to_string(),
                voting_deadline: Some(5),
                deposit: Some(GOVERNANCE_DEFAULT_DEPOSIT),
            })
            .unwrap(),
        );
        state
            .apply_transition(StateTransition::ProcessGovernanceTransaction {
                tx: proposal,
                current_block: 1,
            })
            .unwrap();

        // Positive: a valid V1 legacy signature is accepted at the apply path.
        let good_vote = gov_tx(
            voter_good,
            TransactionType::GovernanceVote,
            signed_vote_json("vp1", true, None, &sk_good, &pk_good),
        );
        state
            .apply_transition(StateTransition::ProcessGovernanceTransaction {
                tx: good_vote,
                current_block: 2,
            })
            .expect("a valid V1 legacy governance-vote signature must be accepted end-to-end");

        // Field-binding regression: a signature computed over proposal id
        // "not-vp1" must not validate against proposal id "vp1". This confirms
        // proposal_id is inside the signed preimage and is checked before
        // voting-power and address validation.
        let differently_bound_payload = GovernanceVotePayload {
            proposal_id: "not-vp1".to_string(),
            approve: true,
            voting_power: None,
            signature: None,
            signer_public_key: Some(pk_bad.to_hex()),
        };
        let bad_payload = GovernanceVotePayload {
            proposal_id: "vp1".to_string(),
            approve: true,
            voting_power: None,
            signature: Some(
                sk_bad
                    .sign(
                        differently_bound_payload
                            .canonical_signing_message()
                            .as_bytes(),
                    )
                    .to_hex(),
            ),
            signer_public_key: Some(pk_bad.to_hex()),
        };
        let bad_vote = gov_tx(
            voter_bad,
            TransactionType::GovernanceVote,
            serde_json::to_string(&bad_payload).unwrap(),
        );
        let err = state
            .apply_transition(StateTransition::ProcessGovernanceTransaction {
                tx: bad_vote,
                current_block: 3,
            })
            .expect_err("a governance vote whose signature does not verify must be rejected");
        assert!(
            matches!(&err, StateError::Governance(m) if m.contains("Invalid governance vote signature")),
            "expected the signature gate to reject the mismatched preimage, got {err:?}"
        );
    }

    /// Production-seam regression for #2229/#2500: governance-vote signature
    /// verification must select the preimage version from `current_block`.
    /// Replacing the height-aware call with the ambient-version helper makes
    /// this test fail without changing the payload-level tests.
    #[test]
    fn governance_vote_apply_uses_height_derived_protocol_version_2229() {
        let source = include_str!("state.rs");
        let vote_branch = source
            .split_once("TransactionType::GovernanceVote =>")
            .expect("governance-vote apply branch must exist")
            .1
            .split_once("TransactionType::GovernanceFinalize =>")
            .expect("governance-vote apply branch must remain bounded")
            .0;

        assert!(
            vote_branch.contains("payload.verify_vote_signature_at_height(current_block)"),
            "governance-vote apply must derive its signing protocol from current_block"
        );
        assert!(
            !vote_branch.contains("payload.verify_vote_signature()"),
            "governance-vote apply must not use the process-global protocol version"
        );
    }

