    #[test]
    fn set_oracle_config_rejects_invalid_parameters() {
        let mut state = State::new();
        let (_oracle_valid_sk, oracle_valid_id) = oracle_identity(401);

        let err_empty = state
            .apply_transition(StateTransition::SetOracleConfig {
                oracle_set: vec![],
                oracle_quorum: 1,
            })
            .expect_err("empty oracle set must be rejected");
        assert!(err_empty.to_string().contains("oracle_set"));

        let err_zero = state
            .apply_transition(StateTransition::SetOracleConfig {
                oracle_set: vec![oracle_valid_id.clone()],
                oracle_quorum: 0,
            })
            .expect_err("zero quorum must be rejected");
        assert!(err_zero.to_string().contains("oracle_quorum"));

        let err_too_high = state
            .apply_transition(StateTransition::SetOracleConfig {
                oracle_set: vec![oracle_valid_id],
                oracle_quorum: 2,
            })
            .expect_err("quorum above set size must be rejected");
        assert!(err_too_high.to_string().contains("oracle_quorum"));

        let err_invalid_key = state
            .apply_transition(StateTransition::SetOracleConfig {
                oracle_set: vec!["oracle-a".to_string()],
                oracle_quorum: 1,
            })
            .expect_err("invalid oracle id format must be rejected");
        assert!(err_invalid_key.to_string().contains("ed25519"));
    }

    #[test]
    fn governance_rejects_oracle_quorum_above_set_size() {
        let mut state = State::new();
        let proposer = addr(11);
        let (_oracle_a_sk, oracle_a_id) = oracle_identity(501);
        let (_oracle_b_sk, oracle_b_id) = oracle_identity(502);
        let (sk, pk, voter) = governance_voter(9008);
        state.create_account(proposer, Balance::new(10_000));
        fund_governance_voter(&mut state, voter, 10);
        state
            .apply_transition(StateTransition::SetOracleConfig {
                oracle_set: vec![oracle_a_id, oracle_b_id],
                oracle_quorum: 2,
            })
            .unwrap();

        let mut proposal_tx = Transaction::new(
            vec![],
            vec![crate::blockchain::transaction::TransactionOutput {
                amount: 0,
                address: "0x1111111111111111111111111111111111111111".to_string(),
                script: "OP_TRUE".to_string(),
                nft_data: None,
            }],
        );
        proposal_tx.sender_address = proposer;
        proposal_tx.tx_type = TransactionType::GovernanceProposal;
        proposal_tx.data = Some(
            serde_json::to_string(&GovernanceProposalPayload {
                proposal_id: "p-invalid-q".to_string(),
                parameter: "oracle_quorum".to_string(),
                value: "3".to_string(),
                voting_deadline: Some(3),
                deposit: Some(GOVERNANCE_DEFAULT_DEPOSIT),
            })
            .unwrap(),
        );
        proposal_tx.set_id();
        state
            .apply_transition(StateTransition::ProcessGovernanceTransaction {
                tx: proposal_tx,
                current_block: 1,
            })
            .unwrap();

        let mut vote_tx = Transaction::new(
            vec![],
            vec![crate::blockchain::transaction::TransactionOutput {
                amount: 0,
                address: "0x2222222222222222222222222222222222222222".to_string(),
                script: "OP_TRUE".to_string(),
                nft_data: None,
            }],
        );
        vote_tx.sender_address = voter;
        vote_tx.tx_type = TransactionType::GovernanceVote;
        vote_tx.data = Some(signed_vote_json("p-invalid-q", true, Some(10), &sk, &pk));
        vote_tx.set_id();
        state
            .apply_transition(StateTransition::ProcessGovernanceTransaction {
                tx: vote_tx,
                current_block: 2,
            })
            .unwrap();

        state
            .apply_transition(StateTransition::FinalizeGovernanceProposal {
                proposal_id: "p-invalid-q".to_string(),
                current_block: 4,
                current_timestamp: 4,
            })
            .expect("invalid execution should still finalize deterministically");
        let proposal = state.governance.proposals.get("p-invalid-q").unwrap();
        assert_eq!(proposal.status, GovernanceProposalStatus::FailedExecution);
        assert_eq!(proposal.finalized_at_block, Some(4));
        assert!(
            proposal
                .execution_error
                .as_deref()
                .unwrap_or_default()
                .contains("oracle_quorum")
        );
    }

