    #[test]
    fn governance_rejects_duplicate_vote_from_same_voter() {
        let mut state = State::new();
        let proposer = addr(15);
        let (sk, pk, voter) = governance_voter(9009);
        state.create_account(proposer, Balance::new(20_000));
        fund_governance_voter(&mut state, voter, 10);

        let mut proposal_tx = Transaction::new(
            vec![],
            vec![crate::blockchain::transaction::TransactionOutput {
                amount: 0,
                address: "0x3232323232323232323232323232323232323232".to_string(),
                script: "OP_TRUE".to_string(),
                nft_data: None,
            }],
        );
        proposal_tx.sender_address = proposer;
        proposal_tx.tx_type = TransactionType::GovernanceProposal;
        proposal_tx.data = Some(
            serde_json::to_string(&GovernanceProposalPayload {
                proposal_id: "p-dup-vote".to_string(),
                parameter: "emission_rate".to_string(),
                value: "88".to_string(),
                voting_deadline: Some(5),
                deposit: Some(GOVERNANCE_DEFAULT_DEPOSIT),
            })
            .unwrap(),
        );
        proposal_tx.set_id();
        state
            .apply_transition(StateTransition::ProcessGovernanceTransaction {
                tx: proposal_tx,
                current_block: 1,
            })
            .unwrap();

        let mut first_vote_tx = Transaction::new(
            vec![],
            vec![crate::blockchain::transaction::TransactionOutput {
                amount: 0,
                address: "0x3333333333333333333333333333333333333333".to_string(),
                script: "OP_TRUE".to_string(),
                nft_data: None,
            }],
        );
        first_vote_tx.sender_address = voter;
        first_vote_tx.tx_type = TransactionType::GovernanceVote;
        first_vote_tx.data = Some(signed_vote_json("p-dup-vote", true, Some(10), &sk, &pk));
        first_vote_tx.set_id();
        state
            .apply_transition(StateTransition::ProcessGovernanceTransaction {
                tx: first_vote_tx,
                current_block: 2,
            })
            .unwrap();

        let mut duplicate_vote_tx = Transaction::new(
            vec![],
            vec![crate::blockchain::transaction::TransactionOutput {
                amount: 0,
                address: "0x3434343434343434343434343434343434343434".to_string(),
                script: "OP_TRUE".to_string(),
                nft_data: None,
            }],
        );
        duplicate_vote_tx.sender_address = voter;
        duplicate_vote_tx.nonce = state
            .get_account(&voter)
            .map(|account| account.nonce)
            .unwrap_or_default();
        duplicate_vote_tx.tx_type = TransactionType::GovernanceVote;
        duplicate_vote_tx.data = Some(signed_vote_json("p-dup-vote", false, Some(10), &sk, &pk));
        duplicate_vote_tx.set_id();
        let err = state
            .apply_transition(StateTransition::ProcessGovernanceTransaction {
                tx: duplicate_vote_tx,
                current_block: 3,
            })
            .expect_err("duplicate vote should be rejected");

        assert!(
            matches!(
                err,
                StateError::Governance(ref message) if message == "Voter already cast a ballot"
            ),
            "expected duplicate-ballot governance error, got: {err:?}"
        );
        let proposal = state.governance.proposals.get("p-dup-vote").unwrap();
        assert_eq!(proposal.yes_votes, 10);
        assert_eq!(proposal.no_votes, 0);
        assert_eq!(proposal.votes_by_voter.len(), 1);
    }

    #[test]
    fn governance_votes_use_submission_snapshot_after_stake_increase() {
        let mut state = State::new();
        let proposer = addr(17);
        let (sk, pk, voter) = governance_voter(9010);
        let passive_voter = addr(19);
        let (_oracle_a_sk, oracle_a_id) = oracle_identity(601);
        let (_oracle_b_sk, oracle_b_id) = oracle_identity(602);
        state.create_account(proposer, Balance::new(20_000));
        fund_governance_voter(&mut state, voter, 10);
        fund_governance_voter(&mut state, passive_voter, 90);
        state
            .apply_transition(StateTransition::SetOracleConfig {
                oracle_set: vec![oracle_a_id, oracle_b_id],
                oracle_quorum: 2,
            })
            .unwrap();

        let mut proposal_tx = Transaction::new(
            vec![],
            vec![crate::blockchain::transaction::TransactionOutput {
                amount: 0,
                address: "0x3535353535353535353535353535353535353535".to_string(),
                script: "OP_TRUE".to_string(),
                nft_data: None,
            }],
        );
        proposal_tx.sender_address = proposer;
        proposal_tx.tx_type = TransactionType::GovernanceProposal;
        proposal_tx.data = Some(
            serde_json::to_string(&GovernanceProposalPayload {
                proposal_id: "p-snapshot-vote".to_string(),
                parameter: "oracle_quorum".to_string(),
                value: "1".to_string(),
                voting_deadline: Some(5),
                deposit: Some(GOVERNANCE_DEFAULT_DEPOSIT),
            })
            .unwrap(),
        );
        proposal_tx.set_id();
        state
            .apply_transition(StateTransition::ProcessGovernanceTransaction {
                tx: proposal_tx,
                current_block: 1,
            })
            .unwrap();

        let created = state
            .governance
            .proposals
            .get("p-snapshot-vote")
            .expect("proposal must be created");
        assert_eq!(created.eligible_voting_power, 100);
        assert_eq!(
            created
                .eligible_voting_power_by_voter
                .get(&voter.to_string())
                .copied(),
            Some(10)
        );

        fund_governance_voter(&mut state, voter, 90);
        assert_eq!(
            state.accounts.get(&voter).unwrap().stake_locked,
            Balance::new(100)
        );

        let mut vote_tx = Transaction::new(
            vec![],
            vec![crate::blockchain::transaction::TransactionOutput {
                amount: 0,
                address: "0x3636363636363636363636363636363636363636".to_string(),
                script: "OP_TRUE".to_string(),
                nft_data: None,
            }],
        );
        vote_tx.sender_address = voter;
        vote_tx.tx_type = TransactionType::GovernanceVote;
        vote_tx.data = Some(signed_vote_json("p-snapshot-vote", true, Some(10), &sk, &pk));
        vote_tx.set_id();
        state
            .apply_transition(StateTransition::ProcessGovernanceTransaction {
                tx: vote_tx,
                current_block: 2,
            })
            .unwrap();

        let proposal = state.governance.proposals.get("p-snapshot-vote").unwrap();
        assert_eq!(proposal.yes_votes, 10);
        assert_eq!(proposal.no_votes, 0);
        assert_eq!(
            proposal
                .votes_by_voter
                .get(&voter.to_string())
                .map(|record| record.voting_power),
            Some(10)
        );

        state
            .apply_transition(StateTransition::FinalizeGovernanceProposal {
                proposal_id: "p-snapshot-vote".to_string(),
                current_block: 6,
                current_timestamp: 6,
            })
            .unwrap();

        let proposal = state.governance.proposals.get("p-snapshot-vote").unwrap();
        assert_eq!(proposal.status, GovernanceProposalStatus::FailedQuorum);
        assert_eq!(proposal.finalized_at_block, Some(6));
        assert_eq!(state.governance.params.oracle_quorum, 2);
    }

    #[test]
    fn governance_rejects_vote_after_deadline() {
        let mut state = State::new();
        let proposer = addr(20);
        let (sk, pk, voter) = governance_voter(9020);
        state.create_account(proposer, Balance::new(20_000));
        fund_governance_voter(&mut state, voter, 10);

        let mut proposal_tx = Transaction::new(
            vec![],
            vec![crate::blockchain::transaction::TransactionOutput {
                amount: 0,
                address: "0x3535353535353535353535353535353535353535".to_string(),
                script: "OP_TRUE".to_string(),
                nft_data: None,
            }],
        );
        proposal_tx.sender_address = proposer;
        proposal_tx.tx_type = TransactionType::GovernanceProposal;
        proposal_tx.data = Some(
            serde_json::to_string(&GovernanceProposalPayload {
                proposal_id: "p-late-vote".to_string(),
                parameter: "emission_rate".to_string(),
                value: "99".to_string(),
                voting_deadline: Some(2),
                deposit: Some(GOVERNANCE_DEFAULT_DEPOSIT),
            })
            .unwrap(),
        );
        proposal_tx.set_id();
        state
            .apply_transition(StateTransition::ProcessGovernanceTransaction {
                tx: proposal_tx,
                current_block: 1,
            })
            .unwrap();

        let mut late_vote_tx = Transaction::new(
            vec![],
            vec![crate::blockchain::transaction::TransactionOutput {
                amount: 0,
                address: "0x3636363636363636363636363636363636363636".to_string(),
                script: "OP_TRUE".to_string(),
                nft_data: None,
            }],
        );
        late_vote_tx.sender_address = voter;
        late_vote_tx.tx_type = TransactionType::GovernanceVote;
        late_vote_tx.data =
            Some(signed_vote_json("p-late-vote", true, Some(10), &sk, &pk));
        late_vote_tx.set_id();
        let err = state
            .apply_transition(StateTransition::ProcessGovernanceTransaction {
                tx: late_vote_tx,
                current_block: 2,
            })
            .expect_err("vote at or after the deadline should be rejected");

        assert!(err.to_string().contains("Voting period has ended"));
        let proposal = state.governance.proposals.get("p-late-vote").unwrap();
        assert_eq!(proposal.status, GovernanceProposalStatus::Active);
        assert_eq!(proposal.yes_votes, 0);
        assert_eq!(proposal.no_votes, 0);
    }

    #[test]
    fn governance_rejects_vote_missing_signer_public_key_above_activation() {
        let mut state = State::new();
        let proposer = addr(30);
        let voter = addr(31);
        state.create_account(proposer, Balance::new(20_000));
        fund_governance_voter(&mut state, voter, 10);

        // Create proposal at a height above signature activation
        let activation =
            crate::consensus::proof_of_publishing::GOVERNANCE_VOTE_SIGNATURE_ACTIVATION_HEIGHT;
        let mut proposal_tx = Transaction::new(
            vec![],
            vec![crate::blockchain::transaction::TransactionOutput {
                amount: 0,
                address: "0x4040404040404040404040404040404040404040".to_string(),
                script: "OP_TRUE".to_string(),
                nft_data: None,
            }],
        );
        proposal_tx.sender_address = proposer;
        proposal_tx.tx_type = TransactionType::GovernanceProposal;
        proposal_tx.data = Some(
            serde_json::to_string(&GovernanceProposalPayload {
                proposal_id: "p-missing-signer".to_string(),
                parameter: "emission_rate".to_string(),
                value: "42".to_string(),
                voting_deadline: Some(activation + 10),
                deposit: Some(GOVERNANCE_DEFAULT_DEPOSIT),
            })
            .unwrap(),
        );
        proposal_tx.set_id();
        state
            .apply_transition(StateTransition::ProcessGovernanceTransaction {
                tx: proposal_tx,
                current_block: activation,
            })
            .unwrap();

        // Vote with missing signer_public_key — should be rejected, not panic
        let mut vote_tx = Transaction::new(
            vec![],
            vec![crate::blockchain::transaction::TransactionOutput {
                amount: 0,
                address: "0x4141414141414141414141414141414141414141".to_string(),
                script: "OP_TRUE".to_string(),
                nft_data: None,
            }],
        );
        vote_tx.sender_address = voter;
        vote_tx.tx_type = TransactionType::GovernanceVote;
        vote_tx.data = Some(
            serde_json::to_string(&GovernanceVotePayload {
                proposal_id: "p-missing-signer".to_string(),
                approve: true,
                voting_power: Some(10),
                signature: None,
                signer_public_key: None,
            })
            .unwrap(),
        );
        vote_tx.set_id();
        let err = state
            .apply_transition(StateTransition::ProcessGovernanceTransaction {
                tx: vote_tx,
                current_block: activation + 1,
            })
            .expect_err(
                "vote without signer_public_key should be rejected above activation height",
            );
        assert!(err.to_string().contains("signature and signer_public_key"));
    }

    #[test]
    fn governance_weather_policy_update_is_applied_to_reveal_validation() {
        let mut state = State::new();
        state
            .apply_governance_update(
                GovernanceParameterUpdate::WeatherTempDeltaPerSecond(0.001),
                None,
                None,
            )
            .unwrap();

        let station_id = "station-weather-governance";
        let contribution_type = "contribution";
        let nonce_a = "nonce-a";
        let timestamp_a = 1_700_100_000_i64;
        let data_a = serde_json::json!({
            "temperature": 20.0,
            "humidity": 65.0,
            "pressure": 1006.0,
            "dewpoint": 12.0
        });
        let commit_id_a = Transaction::compute_commit_id(
            &data_a,
            nonce_a,
            station_id,
            timestamp_a,
            contribution_type,
        );

        state
            .apply_transition(StateTransition::RegisterCommit {
                payload: CommitPayload {
                    commit_id: commit_id_a.clone(),
                    station_id: station_id.to_string(),
                    timestamp: timestamp_a,
                    contribution_type: contribution_type.to_string(),
                    auth_pubkey: None,
                    auth_signature: None,
                },
                block_height: 100,
            })
            .unwrap();

        state
            .apply_transition(StateTransition::ApplyReveal {
                payload: RevealPayload {
                    commit_id: commit_id_a,
                    station_id: station_id.to_string(),
                    timestamp: timestamp_a,
                    contribution_type: contribution_type.to_string(),
                    data: data_a,
                    nonce: nonce_a.to_string(),
                    data_cid: None,
                    data_hash: None,
                    storage_provider: None,
                    provenance: None,
                    manifest: None,
                    verification_receipt: None,
                    compute_receipt: None,
                quality_tier: None,
                },
                block_height: 101,
                block_timestamp: 0,
            })
            .unwrap();

        let nonce_b = "nonce-b";
        let timestamp_b = 1_700_100_060_i64;
        let data_b = serde_json::json!({
            "temperature": 20.3,
            "humidity": 65.1,
            "pressure": 1006.0,
            "dewpoint": 12.1
        });
        let commit_id_b = Transaction::compute_commit_id(
            &data_b,
            nonce_b,
            station_id,
            timestamp_b,
            contribution_type,
        );

        state
            .apply_transition(StateTransition::RegisterCommit {
                payload: CommitPayload {
                    commit_id: commit_id_b.clone(),
                    station_id: station_id.to_string(),
                    timestamp: timestamp_b,
                    contribution_type: contribution_type.to_string(),
                    auth_pubkey: None,
                    auth_signature: None,
                },
                block_height: 102,
            })
            .unwrap();

        let err = state
            .apply_transition(StateTransition::ApplyReveal {
                payload: RevealPayload {
                    commit_id: commit_id_b,
                    station_id: station_id.to_string(),
                    timestamp: timestamp_b,
                    contribution_type: contribution_type.to_string(),
                    data: data_b,
                    nonce: nonce_b.to_string(),
                    data_cid: None,
                    data_hash: None,
                    storage_provider: None,
                    provenance: None,
                    manifest: None,
                    verification_receipt: None,
                    compute_receipt: None,
                quality_tier: None,
                },
                block_height: 103,
                block_timestamp: 0,
            })
            .expect_err("strict governance weather policy should reject fast temperature delta");
        assert!(err.to_string().contains("temperature changed too quickly"));
    }

