    #[test]
    fn parse_governance_update_supports_pop_assignment_scarcity_and_multidomain_keys() {
        let state = State::new();

        let activation = state
            .parse_governance_update("pop.useful_work_activation_height", "0")
            .expect("pop activation key should parse");
        assert!(matches!(
            activation,
            GovernanceParameterUpdate::PopUsefulWorkActivationHeight(0)
        ));

        let err = state
            .parse_governance_update("pop.useful_work_activation_height", "123")
            .expect_err("non-zero activation height must be rejected");
        assert!(
            err.to_string().contains("must be 0"),
            "expected useful-work-only parser guard, got {err}"
        );

        let assignment = state
            .parse_governance_update("task_assigner.underserved_bonus_multiplier", "1.6")
            .expect("task assigner bonus should parse");
        assert!(matches!(
            assignment,
            GovernanceParameterUpdate::TaskAssignerUnderservedBonusMultiplier(value)
                if (value - 1.6).abs() < f64::EPSILON
        ));

        let scarcity = state
            .parse_governance_update("scarcity.proximity_multiplier", "0.8")
            .expect("scarcity proximity should parse");
        assert!(matches!(
            scarcity,
            GovernanceParameterUpdate::ScarcityProximityMultiplier(value)
                if (value - 0.8).abs() < f64::EPSILON
        ));

        let multidomain = state
            .parse_governance_update("multidomain.hydrology_enabled", "true")
            .expect("multidomain hydrology enabled should parse");
        assert!(matches!(
            multidomain,
            GovernanceParameterUpdate::MultidomainHydrologyEnabled(true)
        ));
    }

    #[test]
    fn governance_policy_updates_apply_and_validate_new_consensus_fields() {
        let mut state = State::new();
        state
            .apply_governance_update(
                GovernanceParameterUpdate::PopUsefulWorkActivationHeight(0),
                None,
                None,
            )
            .expect("activation height lock should accept only 0");
        state
            .apply_governance_update(
                GovernanceParameterUpdate::TaskAssignerUnderservedBonusMultiplier(1.3),
                None,
                None,
            )
            .expect("task assigner update should succeed");
        state
            .apply_governance_update(
                GovernanceParameterUpdate::ScarcityDataDesertMultiplier(1.4),
                None,
                None,
            )
            .expect("scarcity update should succeed");
        state
            .apply_governance_update(
                GovernanceParameterUpdate::MultidomainSoilWeight(1.1),
                None,
                None,
            )
            .expect("multidomain weight update should succeed");

        assert_eq!(
            state
                .governance
                .params
                .pop_liveness_policy
                .useful_work_activation_height,
            0
        );
        assert!(
            (state
                .governance
                .params
                .task_assigner_policy
                .underserved_bonus_multiplier
                - 1.3)
                .abs()
                < f64::EPSILON
        );
        assert!(
            (state
                .governance
                .params
                .scarcity_policy
                .data_desert_multiplier
                - 1.4)
                .abs()
                < f64::EPSILON
        );
        assert!(
            (state
                .governance
                .params
                .multidomain_reward_policy
                .soil_weight
                - 1.1)
                .abs()
                < f64::EPSILON
        );
    }

