    #[test]
    fn governance_parameters_backward_compat_defaults_missing_new_fields() {
        let mut json = serde_json::to_value(GovernanceParameters::default())
            .expect("governance params should serialize");
        let map = json
            .as_object_mut()
            .expect("governance params should serialize to object");
        map.remove("pop_liveness_policy");
        map.remove("task_assigner_policy");
        map.remove("scarcity_policy");
        map.remove("multidomain_reward_policy");

        let decoded: GovernanceParameters =
            serde_json::from_value(json).expect("missing new fields should deserialize");

        assert_eq!(decoded.pop_liveness_policy.useful_work_activation_height, 0);
        assert_eq!(decoded.task_assigner_policy, TaskAssignerPolicy::default());
        assert_eq!(decoded.scarcity_policy, ScarcityPolicy::default());
        assert_eq!(
            decoded.multidomain_reward_policy,
            MultidomainRewardPolicy::default()
        );
    }

