    #[test]
    fn governance_contributor_tier_policy_update_is_applied_and_validated() {
        let mut state = State::new();
        state
            .apply_governance_update(
                GovernanceParameterUpdate::ContributorTrustedProviderAllowedFormatFamilies(vec![
                    "structured".to_string(),
                    "metar".to_string(),
                    "structured".to_string(),
                ]),
                None,
                None,
            )
            .expect("trusted provider format policy update should succeed");
        state
            .apply_governance_update(
                GovernanceParameterUpdate::ContributorTrustedProviderStationAllowlist(vec![
                    " station-a ".to_string(),
                    "station-b".to_string(),
                    "".to_string(),
                ]),
                None,
                None,
            )
            .expect("trusted provider station allowlist update should succeed");

        let policy = &state.governance.params.contributor_tier_policy;
        assert_eq!(
            policy.trusted_provider.allowed_format_families,
            vec!["metar".to_string(), "structured".to_string()]
        );
        assert!(policy.trusted_provider_station_ids.contains("station-a"));
        assert!(policy.trusted_provider_station_ids.contains("station-b"));
        assert_eq!(policy.trusted_provider_station_ids.len(), 2);

        let err = state
            .apply_governance_update(
                GovernanceParameterUpdate::ContributorVerifiedAllowedFormatFamilies(vec![]),
                None,
                None,
            )
            .expect_err("verified station allowlist cannot be empty while inline max > 0");
        assert!(
            err.to_string()
                .contains("verified_station inline policy requires at least one allowed format")
        );
    }

    #[test]
    fn governance_trust_weight_policy_update_is_applied_and_validated() {
        let mut state = State::new();
        assert_eq!(
            state
                .governance
                .params
                .trust_weighting_policy
                .unverified_weight,
            1.0
        );
        assert_eq!(
            state
                .governance
                .params
                .trust_weighting_policy
                .verified_station_weight,
            1.0
        );
        assert_eq!(
            state
                .governance
                .params
                .trust_weighting_policy
                .trusted_provider_weight,
            1.0
        );

        state
            .apply_governance_update(
                GovernanceParameterUpdate::TrustUnverifiedWeight(0.60),
                None,
                None,
            )
            .expect("unverified trust weight update should succeed");
        state
            .apply_governance_update(
                GovernanceParameterUpdate::TrustVerifiedStationWeight(0.80),
                None,
                None,
            )
            .expect("verified station trust weight update should succeed");
        state
            .apply_governance_update(
                GovernanceParameterUpdate::TrustTrustedProviderWeight(1.00),
                None,
                None,
            )
            .expect("trusted provider trust weight update should succeed");

        let trust = &state.governance.params.trust_weighting_policy;
        assert!((trust.unverified_weight - 0.60).abs() < f64::EPSILON);
        assert!((trust.verified_station_weight - 0.80).abs() < f64::EPSILON);
        assert!((trust.trusted_provider_weight - 1.00).abs() < f64::EPSILON);

        let err = state
            .apply_governance_update(
                GovernanceParameterUpdate::TrustVerifiedStationWeight(0.50),
                None,
                None,
            )
            .expect_err("verified weight below unverified should fail");
        assert!(
            err.to_string()
                .contains("trust.verified_station_weight must be >= trust.unverified_weight")
        );
    }

