    #[test]
    fn governance_strict_v1_update_is_applied_to_reveal_validation() {
        let mut state = State::new();
        let station_id = "station-strict-v1-governance";
        let contribution_type = "contribution";

        let timestamp_a = 1_700_200_000_i64;
        let nonce_a = "strict-v1-nonce-a";
        let alias_v1_data = serde_json::json!({
            "schema_version": "wrf.weather.observation.v1",
            "observation": {
                "temperature": 21.0,
                "pressure": 1008.0,
                "dewpoint": 11.0
            }
        });
        let commit_id_a = Transaction::compute_commit_id(
            &alias_v1_data,
            nonce_a,
            station_id,
            timestamp_a,
            contribution_type,
        );

        state
            .apply_transition(StateTransition::RegisterCommit {
                payload: CommitPayload {
                    commit_id: commit_id_a.clone(),
                    station_id: station_id.to_string(),
                    timestamp: timestamp_a,
                    contribution_type: contribution_type.to_string(),
                    auth_pubkey: None,
                    auth_signature: None,
                },
                block_height: 200,
            })
            .expect("commit registration should pass before strict mode is enabled");

        state
            .apply_transition(StateTransition::ApplyReveal {
                payload: RevealPayload {
                    commit_id: commit_id_a,
                    station_id: station_id.to_string(),
                    timestamp: timestamp_a,
                    contribution_type: contribution_type.to_string(),
                    data: alias_v1_data.clone(),
                    nonce: nonce_a.to_string(),
                    data_cid: None,
                    data_hash: None,
                    storage_provider: None,
                    provenance: None,
                    manifest: None,
                    verification_receipt: None,
                    compute_receipt: None,
                quality_tier: None,
                },
                block_height: 201,
                block_timestamp: 0,
            })
            .expect("alias v1 reveal should pass while strict mode is disabled");

        state
            .apply_governance_update(
                GovernanceParameterUpdate::WeatherStrictV1ObservationKeys(true),
                None,
                None,
            )
            .expect("strict v1 governance update should succeed");

        let timestamp_b = 1_700_200_060_i64;
        let nonce_b = "strict-v1-nonce-b";
        let commit_id_b = Transaction::compute_commit_id(
            &alias_v1_data,
            nonce_b,
            station_id,
            timestamp_b,
            contribution_type,
        );

        state
            .apply_transition(StateTransition::RegisterCommit {
                payload: CommitPayload {
                    commit_id: commit_id_b.clone(),
                    station_id: station_id.to_string(),
                    timestamp: timestamp_b,
                    contribution_type: contribution_type.to_string(),
                    auth_pubkey: None,
                    auth_signature: None,
                },
                block_height: 202,
            })
            .expect("commit registration should pass after strict mode is enabled");

        let err = state
            .apply_transition(StateTransition::ApplyReveal {
                payload: RevealPayload {
                    commit_id: commit_id_b,
                    station_id: station_id.to_string(),
                    timestamp: timestamp_b,
                    contribution_type: contribution_type.to_string(),
                    data: alias_v1_data,
                    nonce: nonce_b.to_string(),
                    data_cid: None,
                    data_hash: None,
                    storage_provider: None,
                    provenance: None,
                    manifest: None,
                    verification_receipt: None,
                    compute_receipt: None,
                quality_tier: None,
                },
                block_height: 203,
                block_timestamp: 0,
            })
            .expect_err("strict v1 governance mode should reject alias observation keys");
        assert!(
            err.to_string()
                .contains("recognized canonical weather field")
        );
    }

