    #[test]
    fn governance_law_book_create_and_amend_summary_flow() {
        let mut state = State::new();
        let proposer = addr(50);
        let (create_sk, create_pk, create_voter) = governance_voter(9050);
        let (amend_sk, amend_pk, amend_voter) = governance_voter(9051);
        state.create_account(proposer, Balance::new(20_000));
        fund_governance_voter(&mut state, create_voter, 10);

        let mut create_tx = Transaction::new(
            vec![],
            vec![crate::blockchain::transaction::TransactionOutput {
                amount: 0,
                address: "0x3333333333333333333333333333333333333333".to_string(),
                script: "OP_TRUE".to_string(),
                nft_data: None,
            }],
        );
        create_tx.sender_address = proposer;
        create_tx.tx_type = TransactionType::GovernanceProposal;
        create_tx.data = Some(
            serde_json::to_string(&GovernanceProposalPayload {
                proposal_id: "law-p1".to_string(),
                parameter: "law.create".to_string(),
                value: serde_json::json!({
                    "law_id": "LAW-001-CID-MANDATORY",
                    "title": "CID mandatory for untrusted contributors",
                    "category": "data_submission",
                    "summary": "Untrusted contributors must use CID references.",
                    "enforcement_level": "consensus",
                    "status": "active"
                })
                .to_string(),
                voting_deadline: Some(5),
                deposit: Some(GOVERNANCE_DEFAULT_DEPOSIT),
            })
            .unwrap(),
        );
        create_tx.set_id();
        state
            .apply_transition(StateTransition::ProcessGovernanceTransaction {
                tx: create_tx,
                current_block: 1,
            })
            .unwrap();

        let mut vote_create_tx = Transaction::new(
            vec![],
            vec![crate::blockchain::transaction::TransactionOutput {
                amount: 0,
                address: "0x4444444444444444444444444444444444444444".to_string(),
                script: "OP_TRUE".to_string(),
                nft_data: None,
            }],
        );
        vote_create_tx.sender_address = create_voter;
        vote_create_tx.tx_type = TransactionType::GovernanceVote;
        vote_create_tx.data =
            Some(signed_vote_json("law-p1", true, Some(10), &create_sk, &create_pk));
        vote_create_tx.set_id();
        state
            .apply_transition(StateTransition::ProcessGovernanceTransaction {
                tx: vote_create_tx,
                current_block: 2,
            })
            .unwrap();
        state
            .apply_transition(StateTransition::FinalizeGovernanceProposal {
                proposal_id: "law-p1".to_string(),
                current_block: 6,
                current_timestamp: 6,
            })
            .unwrap();

        let law = state
            .governance
            .law_book
            .laws
            .get("LAW-001-CID-MANDATORY")
            .expect("law should exist after create proposal");
        assert_eq!(law.version, 1);
        assert_eq!(law.status, LawStatus::Active);
        assert_eq!(law.enforcement_level, LawEnforcementLevel::Consensus);
        assert_eq!(law.amendments.len(), 1);
        assert_eq!(law.amendments[0].proposal_id, "law-p1");
        fund_governance_voter(&mut state, amend_voter, 12);

        let mut amend_tx = Transaction::new(
            vec![],
            vec![crate::blockchain::transaction::TransactionOutput {
                amount: 0,
                address: "0x5555555555555555555555555555555555555555".to_string(),
                script: "OP_TRUE".to_string(),
                nft_data: None,
            }],
        );
        amend_tx.sender_address = proposer;
        amend_tx.nonce = state
            .get_account(&proposer)
            .map(|account| account.nonce)
            .unwrap_or_default();
        amend_tx.tx_type = TransactionType::GovernanceProposal;
        amend_tx.data = Some(
            serde_json::to_string(&GovernanceProposalPayload {
                proposal_id: "law-p2".to_string(),
                parameter: "law.amend_summary".to_string(),
                value: serde_json::json!({
                    "law_id": "LAW-001-CID-MANDATORY",
                    "summary": "Untrusted contributors must publish data via CID. Verified stations may submit inline METAR."
                })
                .to_string(),
                voting_deadline: Some(9),
                deposit: Some(GOVERNANCE_DEFAULT_DEPOSIT),
            })
            .unwrap(),
        );
        amend_tx.set_id();
        state
            .apply_transition(StateTransition::ProcessGovernanceTransaction {
                tx: amend_tx,
                current_block: 7,
            })
            .unwrap();

        let mut vote_amend_tx = Transaction::new(
            vec![],
            vec![crate::blockchain::transaction::TransactionOutput {
                amount: 0,
                address: "0x6666666666666666666666666666666666666666".to_string(),
                script: "OP_TRUE".to_string(),
                nft_data: None,
            }],
        );
        vote_amend_tx.sender_address = amend_voter;
        vote_amend_tx.tx_type = TransactionType::GovernanceVote;
        vote_amend_tx.data =
            Some(signed_vote_json("law-p2", true, Some(12), &amend_sk, &amend_pk));
        vote_amend_tx.set_id();
        state
            .apply_transition(StateTransition::ProcessGovernanceTransaction {
                tx: vote_amend_tx,
                current_block: 8,
            })
            .unwrap();
        state
            .apply_transition(StateTransition::FinalizeGovernanceProposal {
                proposal_id: "law-p2".to_string(),
                current_block: 10,
                current_timestamp: 10,
            })
            .unwrap();

        let amended = state
            .governance
            .law_book
            .laws
            .get("LAW-001-CID-MANDATORY")
            .expect("law should still exist after amendment");
        assert_eq!(amended.version, 2);
        assert!(amended.plain_language_summary.contains("Verified stations"));
        assert_eq!(amended.amendments.len(), 2);
        assert_eq!(amended.amendments[1].proposal_id, "law-p2");
    }

