    // ---------------------------------------------------------------------------
    // Layer2 batch proof wiring tests
    // ---------------------------------------------------------------------------

    /// Helper: build a minimal `Layer2BatchSubmit` transaction with the given payload fields.
    fn layer2_batch_tx(proof_hex: &str, commitment_hex: &str, batch_id: u64) -> Transaction {
        let payload = crate::blockchain::transaction::Layer2BatchSubmitPayload {
            batch_id,
            prev_state_root: "prev".to_string(),
            state_root: "next".to_string(),
            proof_hex: proof_hex.to_string(),
            commitment_hex: commitment_hex.to_string(),
            operator: "op1".to_string(),
        };
        let mut tx = Transaction::new(vec![], vec![]);
        tx.tx_type = TransactionType::Layer2BatchSubmit;
        tx.data = Some(serde_json::to_string(&payload).unwrap());
        tx
    }

    /// A test-only ZkVerifier that always returns `Ok(true)`.
    #[derive(Debug)]
    struct AlwaysValidZkVerifier;
    impl crate::consensus::zk_verification::ZkVerifier for AlwaysValidZkVerifier {
        fn verify_range_proof(&self, _: &str, _: &str) -> Result<bool, String> {
            Ok(true)
        }
        fn verify_confidential_transfer(
            &self,
            _: &str,
            _: &str,
            _: &str,
            _: u64,
            _: usize,
            _: usize,
        ) -> Result<bool, String> {
            Ok(true)
        }
        fn verify_selective_disclosure(&self, _: &str, _: &str) -> Result<bool, String> {
            Ok(true)
        }
        fn verify_weather_model(
            &self,
            _: &str,
            _: &str,
            _: &str,
            _: u64,
            _: u64,
        ) -> Result<bool, String> {
            Ok(true)
        }
        fn verify_batch_proof(&self, _: &str, _: &str) -> Result<bool, String> {
            Ok(true)
        }
    }

    /// A test-only ZkVerifier that always returns `Ok(false)`.
    #[derive(Debug)]
    struct AlwaysInvalidZkVerifier;
    impl crate::consensus::zk_verification::ZkVerifier for AlwaysInvalidZkVerifier {
        fn verify_range_proof(&self, _: &str, _: &str) -> Result<bool, String> {
            Ok(false)
        }
        fn verify_confidential_transfer(
            &self,
            _: &str,
            _: &str,
            _: &str,
            _: u64,
            _: usize,
            _: usize,
        ) -> Result<bool, String> {
            Ok(false)
        }
        fn verify_selective_disclosure(&self, _: &str, _: &str) -> Result<bool, String> {
            Ok(false)
        }
        fn verify_weather_model(
            &self,
            _: &str,
            _: &str,
            _: &str,
            _: u64,
            _: u64,
        ) -> Result<bool, String> {
            Ok(false)
        }
        fn verify_batch_proof(&self, _: &str, _: &str) -> Result<bool, String> {
            Ok(false)
        }
    }

    #[test]
    fn layer2_batch_submit_accepted_when_proof_is_valid() {
        let mut state = State::new();
        state.set_zk_verifier(std::sync::Arc::new(AlwaysValidZkVerifier));
        let tx = layer2_batch_tx("aabbcc", "ddeeff", 1);
        let result = state.apply_protocol_transaction(&tx, 0);
        assert!(result.is_ok(), "valid proof should be accepted: {result:?}");
    }

    #[test]
    fn layer2_batch_submit_rejected_when_proof_is_invalid() {
        let mut state = State::new();
        state.set_zk_verifier(std::sync::Arc::new(AlwaysInvalidZkVerifier));
        let tx = layer2_batch_tx("aabbcc", "ddeeff", 2);
        let err = state
            .apply_protocol_transaction(&tx, 0)
            .expect_err("invalid proof should be rejected");
        let msg = err.to_string();
        assert!(
            msg.contains("L2_BATCH_PROOF_INVALID"),
            "error should contain L2_BATCH_PROOF_INVALID, got: {msg}"
        );
    }

    #[test]
    fn layer2_batch_submit_rejected_when_no_zk_feature() {
        // RejectAllZkVerifier is the default; it always returns Err.
        let mut state = State::new();
        // Default verifier is RejectAllZkVerifier — set it explicitly to be clear.
        state.set_zk_verifier(std::sync::Arc::new(
            crate::consensus::zk_verification::RejectAllZkVerifier,
        ));
        let tx = layer2_batch_tx("aabbcc", "ddeeff", 3);
        let err = state
            .apply_protocol_transaction(&tx, 0)
            .expect_err("RejectAllZkVerifier should reject every batch proof");
        let msg = err.to_string();
        assert!(
            msg.contains("L2_BATCH_PROOF_ERROR"),
            "error should contain L2_BATCH_PROOF_ERROR, got: {msg}"
        );
    }

    #[test]
    fn layer2_batch_submit_rejects_malformed_payload() {
        let mut state = State::new();
        state.set_zk_verifier(std::sync::Arc::new(AlwaysValidZkVerifier));
        let mut tx = Transaction::new(vec![], vec![]);
        tx.tx_type = TransactionType::Layer2BatchSubmit;
        tx.data = Some("{not valid json}".to_string());
        let err = state
            .apply_protocol_transaction(&tx, 0)
            .expect_err("malformed payload should be rejected");
        assert!(
            err.to_string().contains("L2_BATCH_PAYLOAD_INVALID"),
            "error should contain L2_BATCH_PAYLOAD_INVALID, got: {err}"
        );
    }

    #[test]
    fn governance_transitions_emit_durable_audit_events() {
        let mut state = State::new();
        let proposer = Address([0x11; 20]);
        state.create_account(proposer, Balance::new(10_000));
        fund_governance_voter(&mut state, proposer, 100);

        state
            .apply_transition(StateTransition::CreateGovernanceProposal {
                proposer,
                proposal_id: "audit-prop-1".to_string(),
                update: GovernanceParameterUpdate::EmissionRate(150),
                voting_deadline: 12,
                deposit: Balance::new(GOVERNANCE_DEFAULT_DEPOSIT),
                created_at_block: 5,
                current_timestamp: 1_700_000_000,
            })
            .expect("proposal creation should succeed");

        state
            .apply_transition(StateTransition::VoteGovernanceProposal {
                proposal_id: "audit-prop-1".to_string(),
                voter: proposer,
                approve: true,
                voting_power: 100,
                current_block: 6,
            })
            .expect("vote should succeed");

        state
            .apply_transition(StateTransition::FinalizeGovernanceProposal {
                proposal_id: "audit-prop-1".to_string(),
                current_block: 12,
                current_timestamp: 1_700_000_100,
            })
            .expect("finalization should succeed");

        assert_eq!(state.audit_events().len(), 2);
        assert_eq!(state.audit_events()[0].event_id, 1);
        assert_eq!(
            state.audit_events()[0].kind,
            AuditEventKind::GovernanceProposalCreated
        );
        assert_eq!(state.audit_events()[0].block_height, 5);
        assert_eq!(
            state.audit_events()[1].kind,
            AuditEventKind::GovernanceProposalExecuted
        );
        assert_eq!(state.audit_events()[1].block_height, 12);
    }

    #[test]
    fn audit_events_roundtrip_and_state_root_are_deterministic() {
        let mut state = State::new();
        state.append_audit_event(AuditEventRecord {
            event_id: 0,
            block_height: 7,
            timestamp: 1_700_000_010,
            kind: AuditEventKind::BridgeSafetyHalt,
            subject_id: Some("bridge-1".to_string()),
            actor_id: Some("operator-a".to_string()),
            details: Some(serde_json::json!({ "reason": "manual" })),
        });
        state.append_audit_event(AuditEventRecord {
            event_id: 0,
            block_height: 8,
            timestamp: 1_700_000_020,
            kind: AuditEventKind::QualitySlashingApplied,
            subject_id: Some("commit-1".to_string()),
            actor_id: Some("0x1111111111111111111111111111111111111111".to_string()),
            details: Some(serde_json::json!({ "slashed_amount": 5 })),
        });

        state.recalculate_state_root();
        let root_before = state.state_root;
        let encoded = serde_json::to_string(&state).expect("state should serialize");
        let mut decoded: State = serde_json::from_str(&encoded).expect("state should deserialize");

        assert_eq!(decoded.audit_events().len(), 2);
        assert_eq!(decoded.audit_events()[0].event_id, 1);
        assert_eq!(decoded.audit_events()[1].event_id, 2);
        decoded.recalculate_state_root();
        assert_eq!(decoded.state_root, root_before);
    }

    #[test]
    fn state_root_distinguishes_u64_reputation_scores() {
        use crate::station_registry::{DataQualityTier, StationLocation, WeatherStation};

        let make_station = |id: &str, score: u64| WeatherStation {
            station_id: id.to_string(),
            owner_address: "owner1".to_string(),
            location: StationLocation {
                latitude: 40.0,
                longitude: -74.0,
                elevation_meters: None,
            },
            hardware_model: "TestHW".to_string(),
            calibration_date: None,
            is_active: true,
            reputation_score: score,
            data_quality_tier: DataQualityTier::Bronze,
            provenance_class: ContributionProvenanceClass::Real,
            ring_public_key: None,
        };

        // Two scores that differ only in the upper 32 bits
        let score_a: u64 = 0x1_0000_0001;
        let score_b: u64 = 0x2_0000_0001;
        assert_eq!(score_a as u32, score_b as u32); // same lower 32 bits

        let mut state_a = State::default();
        state_a
            .station_registry
            .register(make_station("station-aaa", score_a))
            .unwrap();
        state_a.recalculate_state_root();

        let mut state_b = State::default();
        state_b
            .station_registry
            .register(make_station("station-aaa", score_b))
            .unwrap();
        state_b.recalculate_state_root();

        assert_ne!(
            state_a.state_root, state_b.state_root,
            "state roots must differ when reputation scores differ in upper 32 bits"
        );
    }

    // -----------------------------------------------------------------------
    // Anonymous Reward Claim tests
    // -----------------------------------------------------------------------
    use crate::blockchain::transaction::RewardClaimPayload;
    use wrfcoin_privacy::ring_signatures::{KeyImage, MLSAGSignature, RingMember};
    fn random_keypair() -> ([u8; 32], [u8; 32]) {
        use rand::RngCore;
        let mut sk_wide = [0u8; 64];
        rand::rngs::OsRng.fill_bytes(&mut sk_wide);
        let scalar = wrfcoin_privacy::Scalar::from_bytes_mod_order_wide(&sk_wide);
        let pk = wrfcoin_privacy::scalar_to_public_key(&scalar);
        (scalar.to_bytes(), pk)
    }
    fn make_station_with_ring_key(id: &str, ring_pk_hex: &str) -> WeatherStation {
        WeatherStation {
            station_id: id.to_string(),
            owner_address: format!("owner_{id}"),
            location: StationLocation {
                latitude: 0.0,
                longitude: 0.0,
                elevation_meters: None,
            },
            hardware_model: "test".to_string(),
            calibration_date: None,
            is_active: true,
            reputation_score: 50,
            data_quality_tier: DataQualityTier::default(),
            provenance_class: ContributionProvenanceClass::Real,
            ring_public_key: Some(ring_pk_hex.to_string()),
        }
    }
    /// Build a valid reward claim payload and the state pre-populated with ring stations.
    /// Returns (state, payload, current_block).
    fn setup_reward_claim(num_stations: usize) -> (State, RewardClaimPayload, u64) {
        assert!(num_stations >= 2, "need at least 2 for signer + 1 decoy");
        let mut state = State::new();
        let current_block: u64 = 0; // epoch 0
        let epoch = current_block / crate::blockchain::transaction::REWARD_CLAIM_EPOCH_BLOCKS;
        // Generate keypairs for all stations.
        let mut keypairs: Vec<([u8; 32], [u8; 32])> = Vec::new();
        for _ in 0..num_stations {
            keypairs.push(random_keypair());
        }
        // Register stations.
        for (i, (_sk, pk)) in keypairs.iter().enumerate() {
            let station = make_station_with_ring_key(&format!("station-{i}"), &hex::encode(pk));
            state.station_registry.register(station).unwrap();
        }
        // Signer is the first keypair.
        let (signer_sk, _signer_pk) = &keypairs[0];
        // Build ring decoys (all except the signer).
        let decoys: Vec<RingMember> = keypairs[1..]
            .iter()
            .map(|(_, pk)| RingMember { public_key: *pk })
            .collect();
        // Generate key image.
        let key_image = KeyImage::generate(signer_sk).unwrap();
        // Build commitment (dummy 32-byte hex).
        let commitment_hex = "ab".repeat(32);
        let mut payload = RewardClaimPayload {
            epoch,
            ring_signature: String::new(),
            key_image: hex::encode(key_image.to_bytes()),
            amount_commitment: commitment_hex,
            range_proof: "ff".repeat(32),
            destination: "wrf1destination".to_string(),
        };
        let sig = MLSAGSignature::sign(&payload.authorization_message(), signer_sk, &decoys)
            .unwrap();
        payload.ring_signature = hex::encode(serde_json::to_vec(&sig).unwrap());
        (state, payload, current_block)
    }

    #[test]
    fn reward_claim_happy_path() {
        let (mut state, payload, current_block) = setup_reward_claim(8); // 8 stations = ring size 8
        // Build transaction.
        let mut tx = Transaction::new(vec![], vec![]);
        tx.tx_type = TransactionType::RewardClaim;
        tx.data = Some(serde_json::to_string(&payload).unwrap());
        tx.set_id();
        state
            .apply_protocol_transaction(&tx, current_block)
            .expect("reward claim should succeed");
        // Verify key image was recorded.
        let ki_entry = format!("{}:{}", payload.epoch, payload.key_image);
        assert!(state.reward_claim_key_images.contains(&ki_entry));
        // Verify commitment was registered.
        assert!(
            state
                .privacy_commitments
                .contains(&payload.amount_commitment)
        );
    }

