    #[test]
    fn reward_claim_ring_too_small() {
        // Build a valid claim first, then tamper the signature ring below minimum size.
        let (mut state, mut payload, current_block) = setup_reward_claim(8);
        let mut sig: MLSAGSignature =
            serde_json::from_slice(&hex::decode(&payload.ring_signature).unwrap()).unwrap();
        sig.ring.truncate(6);
        payload.ring_signature = hex::encode(serde_json::to_vec(&sig).unwrap());
        let mut tx = Transaction::new(vec![], vec![]);
        tx.tx_type = TransactionType::RewardClaim;
        tx.data = Some(serde_json::to_string(&payload).unwrap());
        tx.set_id();
        let err = state
            .apply_protocol_transaction(&tx, current_block)
            .expect_err("small ring should fail");
        let msg = format!("{err}");
        assert!(
            msg.contains("RING_TOO_SMALL"),
            "error should mention RING_TOO_SMALL, got: {msg}"
        );
    }

