    #[test]
    fn all_six_sets_pruned() {
        let mut state = State::new();
        let height = 50u64;

        // Insert one entry into each of the 6 prunable sets at low height
        state.spent_oracle_nonces.insert("on".into());
        state.spent_oracle_nonces_height.insert("on".into(), height);

        state.privacy_spent_key_images.insert("ki".into());
        state
            .privacy_spent_key_images_height
            .insert("ki".into(), height);

        state.privacy_spent_nullifiers.insert("nf".into());
        state
            .privacy_spent_nullifiers_height
            .insert("nf".into(), height);

        state.privacy_commitments.insert("cm".into());
        state
            .privacy_commitments_height
            .insert("cm".into(), height);

        state.privacy_disclosure_ids.insert("di".into());
        state
            .privacy_disclosure_ids_height
            .insert("di".into(), height);

        state.reward_claim_key_images.insert("rk".into());
        state
            .reward_claim_key_images_height
            .insert("rk".into(), height);

        // Prune at 200_000 (cutoff = 100_000; 50 < 100_000 → all pruned)
        state.prune_expired_state(200_000);

        assert!(state.spent_oracle_nonces.is_empty());
        assert!(state.spent_oracle_nonces_height.is_empty());
        assert!(state.privacy_spent_key_images.is_empty());
        assert!(state.privacy_spent_key_images_height.is_empty());
        assert!(state.privacy_spent_nullifiers.is_empty());
        assert!(state.privacy_spent_nullifiers_height.is_empty());
        assert!(state.privacy_commitments.is_empty());
        assert!(state.privacy_commitments_height.is_empty());
        assert!(state.privacy_disclosure_ids.is_empty());
        assert!(state.privacy_disclosure_ids_height.is_empty());
        assert!(state.reward_claim_key_images.is_empty());
        assert!(state.reward_claim_key_images_height.is_empty());
    }

