    // ── Pruning height tracking (#1202) ─────────────────────────────────

    #[test]
    fn prune_expired_state_records_last_height() {
        let mut state = State::new();
        assert_eq!(state.last_state_pruning_height, 0);

        // Height below retention window — cutoff saturates to 0 so no pruning,
        // but `last_state_pruning_height` should NOT be updated because the
        // function returns early.
        state.prune_expired_state(50);
        assert_eq!(
            state.last_state_pruning_height, 0,
            "height must not update when cutoff == 0 (nothing to prune)"
        );

        // Height above retention window — pruning fires.
        state.prune_expired_state(200_000);
        assert_eq!(
            state.last_state_pruning_height, 200_000,
            "height must record the block at which pruning ran"
        );
    }

    #[test]
    fn prune_set_by_height_prunes_strictly_below_cutoff() {
        let mut set = FxHashSet::default();
        let mut heights = FxHashMap::default();
        for (key, height) in [("below", 99u64), ("at", 100u64), ("above", 101u64)] {
            set.insert(key.to_string());
            heights.insert(key.to_string(), height);
        }

        State::prune_set_by_height(&mut set, &mut heights, 100);

        assert!(
            !set.contains("below") && !heights.contains_key("below"),
            "entries below cutoff must be pruned"
        );
        assert!(
            set.contains("at") && heights.contains_key("at"),
            "entry exactly at cutoff must be retained"
        );
        assert!(
            set.contains("above") && heights.contains_key("above"),
            "entries above cutoff must be retained"
        );
    }

    #[test]
    fn prune_expired_state_at_retention_boundary_does_not_prune_or_update_height() {
        use crate::consensus::proof_of_publishing::DEFAULT_STATE_PRUNING_RETENTION_BLOCKS;

        let mut state = State::new();
        state.spent_oracle_nonces.insert("at-boundary".into());
        state
            .spent_oracle_nonces_height
            .insert("at-boundary".into(), 0);

        // current_height == retention => cutoff == 0, so pruning returns early.
        state.prune_expired_state(DEFAULT_STATE_PRUNING_RETENTION_BLOCKS);

        assert!(
            state.spent_oracle_nonces.contains("at-boundary")
                && state.spent_oracle_nonces_height.contains_key("at-boundary"),
            "cutoff == 0 must not prune entries"
        );
        assert_eq!(
            state.last_state_pruning_height, 0,
            "height must remain unchanged when cutoff == 0"
        );
    }

    #[test]
    fn prune_expired_state_first_height_after_retention_prunes_only_zero_height() {
        use crate::consensus::proof_of_publishing::DEFAULT_STATE_PRUNING_RETENTION_BLOCKS;

        let mut state = State::new();
        for (key, height) in [("h0", 0u64), ("h1", 1u64), ("h2", 2u64)] {
            state.spent_oracle_nonces.insert(key.to_string());
            state
                .spent_oracle_nonces_height
                .insert(key.to_string(), height);
        }

        // current_height == retention + 1 => cutoff == 1.
        state.prune_expired_state(DEFAULT_STATE_PRUNING_RETENTION_BLOCKS + 1);

        assert!(
            !state.spent_oracle_nonces.contains("h0")
                && !state.spent_oracle_nonces_height.contains_key("h0"),
            "entries with height < cutoff must be pruned"
        );
        assert!(
            state.spent_oracle_nonces.contains("h1")
                && state.spent_oracle_nonces_height.contains_key("h1"),
            "entry at cutoff must be retained"
        );
        assert!(
            state.spent_oracle_nonces.contains("h2")
                && state.spent_oracle_nonces_height.contains_key("h2"),
            "entry above cutoff must be retained"
        );
        assert_eq!(
            state.last_state_pruning_height,
            DEFAULT_STATE_PRUNING_RETENTION_BLOCKS + 1,
            "height should update once pruning runs"
        );
    }

    #[test]
    fn prune_expired_state_query_boundary_prunes_height_one_retains_height_two() {
        use crate::consensus::proof_of_publishing::DEFAULT_STATE_PRUNING_RETENTION_BLOCKS;

        let mut state = State::new();
        for (key, height) in [("h1", 1u64), ("h2", 2u64), ("h3", 3u64)] {
            state.spent_oracle_nonces.insert(key.to_string());
            state
                .spent_oracle_nonces_height
                .insert(key.to_string(), height);
        }

        // current_height == retention + 2 => cutoff == 2.
        state.prune_expired_state(DEFAULT_STATE_PRUNING_RETENTION_BLOCKS + 2);

        assert!(
            !state.spent_oracle_nonces.contains("h1")
                && !state.spent_oracle_nonces_height.contains_key("h1"),
            "height 1 is below cutoff and must be pruned"
        );
        assert!(
            state.spent_oracle_nonces.contains("h2")
                && state.spent_oracle_nonces_height.contains_key("h2"),
            "height 2 is exactly at cutoff and must be retained"
        );
        assert!(
            state.spent_oracle_nonces.contains("h3")
                && state.spent_oracle_nonces_height.contains_key("h3"),
            "height 3 is above cutoff and must be retained"
        );
        assert_eq!(
            state.last_state_pruning_height,
            DEFAULT_STATE_PRUNING_RETENTION_BLOCKS + 2,
            "height should update once boundary pruning runs"
        );
    }

    #[test]
    fn state_root_ignores_pruning_height_maps_at_retention_boundary() {
        use crate::consensus::proof_of_publishing::DEFAULT_STATE_PRUNING_RETENTION_BLOCKS;

        let mut state_a = State::new();
        let mut state_b = State::new();

        state_a.privacy_commitments.insert("commitment".into());
        state_b.privacy_commitments.insert("commitment".into());
        state_a
            .privacy_commitments_height
            .insert("commitment".into(), 1);
        state_b
            .privacy_commitments_height
            .insert("commitment".into(), 2);

        state_a.privacy_spent_key_images.insert("key-image".into());
        state_b.privacy_spent_key_images.insert("key-image".into());
        state_a
            .privacy_spent_key_images_height
            .insert("key-image".into(), 1);
        state_b
            .privacy_spent_key_images_height
            .insert("key-image".into(), 2);

        state_a.privacy_spent_nullifiers.insert("nullifier".into());
        state_b.privacy_spent_nullifiers.insert("nullifier".into());
        state_a
            .privacy_spent_nullifiers_height
            .insert("nullifier".into(), 1);
        state_b
            .privacy_spent_nullifiers_height
            .insert("nullifier".into(), 2);

        state_a.privacy_disclosure_ids.insert("disclosure".into());
        state_b.privacy_disclosure_ids.insert("disclosure".into());
        state_a
            .privacy_disclosure_ids_height
            .insert("disclosure".into(), 1);
        state_b
            .privacy_disclosure_ids_height
            .insert("disclosure".into(), 2);

        state_a.spent_oracle_nonces.insert("oracle-nonce".into());
        state_b.spent_oracle_nonces.insert("oracle-nonce".into());
        state_a
            .spent_oracle_nonces_height
            .insert("oracle-nonce".into(), 1);
        state_b
            .spent_oracle_nonces_height
            .insert("oracle-nonce".into(), 2);

        state_a.reward_claim_key_images.insert("reward-key".into());
        state_b.reward_claim_key_images.insert("reward-key".into());
        state_a
            .reward_claim_key_images_height
            .insert("reward-key".into(), 1);
        state_b
            .reward_claim_key_images_height
            .insert("reward-key".into(), 2);

        // At exact retention height, cutoff == 0, so no pruning happens. The
        // states differ only in pruning metadata and must keep the same root.
        state_a.prune_expired_state(DEFAULT_STATE_PRUNING_RETENTION_BLOCKS);
        state_b.prune_expired_state(DEFAULT_STATE_PRUNING_RETENTION_BLOCKS);
        state_a.recalculate_state_root();
        state_b.recalculate_state_root();

        assert_eq!(
            state_a.state_root, state_b.state_root,
            "pruning height maps must remain excluded from the consensus state root"
        );

        state_b.spent_oracle_nonces.insert("root-visible-extra".into());
        state_b.recalculate_state_root();
        assert_ne!(
            state_a.state_root, state_b.state_root,
            "canonical replay-protection sets remain state-root material"
        );
    }

    #[test]
